export const ASSETS: Record<string, DashboardAsset> = {
  "/app/api.js": {"type":"text/javascript; charset=utf-8","body":"let session;\nconst requestError = 'The request could not be completed. Try again.';\nexport function configureSession(value) {\n    session = { ...value };\n}\n/** Canonical JSON is shared as a wire format; the browser never imports server code. */\nexport function canonicalBody(value) {\n    const encode = (item) => {\n        if (item === null)\n            return 'null';\n        if (typeof item === 'string' || typeof item === 'boolean')\n            return JSON.stringify(item);\n        if (typeof item === 'number' && Number.isFinite(item))\n            return JSON.stringify(item);\n        if (Array.isArray(item))\n            return `[${Array.from(item, child => child === undefined ? 'null' : encode(child)).join(',')}]`;\n        if (typeof item === 'object') {\n            const record = item;\n            return `{${Object.keys(record).sort().filter(key => record[key] !== undefined).map(key => `${JSON.stringify(key)}:${encode(record[key])}`).join(',')}}`;\n        }\n        throw new Error();\n    };\n    try {\n        return encode(value);\n    }\n    catch {\n        throw new Error('The request contains an unsupported value.');\n    }\n}\nfunction routeName(route) {\n    const name = route.startsWith('/api/') ? route.slice(5) : route;\n    if (!/^[A-Za-z0-9_-]+(?:\\/[A-Za-z0-9_-]+)*$/.test(name))\n        throw new Error('Choose a valid dashboard action.');\n    return name;\n}\nasync function request(route, method, body, assertion) {\n    const name = routeName(route);\n    const headers = { Accept: 'application/json' };\n    if (method === 'POST') {\n        if (!session)\n            throw new Error('Open keysentry again from your terminal.');\n        headers['Content-Type'] = 'application/json';\n        headers['X-CSRF-Token'] = session.csrf;\n    }\n    if (assertion)\n        headers['X-Passkey-Assertion'] = assertion;\n    try {\n        const response = await fetch(`/api/${name}`, { method, credentials: 'same-origin', cache: 'no-store', redirect: 'error', headers, ...(body === undefined ? {} : { body }) });\n        if (!response.ok)\n            throw new Error();\n        return await response.json();\n    }\n    catch {\n        throw new Error(requestError);\n    }\n}\nexport async function get(route) { return request(route, 'GET'); }\nexport async function post(route, body = {}) { return request(route, 'POST', canonicalBody(body)); }\nexport async function fetchSession() {\n    const value = await get('session');\n    if (typeof value?.csrf !== 'string' || typeof value?.readOnly !== 'boolean' || !Number.isInteger(value?.passkeys) || value.passkeys < 0)\n        throw new Error(requestError);\n    configureSession(value);\n    return { ...value };\n}\nfunction base64url(bytes) {\n    let binary = '';\n    for (const byte of new Uint8Array(bytes))\n        binary += String.fromCharCode(byte);\n    return btoa(binary).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '');\n}\nfunction decode(value) {\n    if (typeof value !== 'string' || !/^[A-Za-z0-9_-]+$/.test(value) || value.length > 100_000)\n        throw new Error(requestError);\n    try {\n        const binary = atob(value.replaceAll('-', '+').replaceAll('_', '/'));\n        const bytes = Uint8Array.from(binary, character => character.charCodeAt(0));\n        if (base64url(bytes.buffer) !== value)\n            throw new Error();\n        return bytes;\n    }\n    catch {\n        throw new Error(requestError);\n    }\n}\nfunction publicOptions(options) { return options.publicKey ?? options; }\nfunction descriptors(value) {\n    if (!Array.isArray(value))\n        return [];\n    return value.map(item => ({ type: 'public-key', id: decode(item.id) }));\n}\nfunction writable() {\n    if (!session)\n        throw new Error('Open keysentry again from your terminal.');\n    if (session.readOnly)\n        throw new Error('Changes are unavailable in this session.');\n}\nfunction credentialWire(credential, registration) {\n    const response = credential.response;\n    const common = { id: credential.id, rawId: base64url(credential.rawId), type: credential.type };\n    if (registration)\n        return { ...common, response: { clientDataJSON: base64url(response.clientDataJSON), attestationObject: base64url(response.attestationObject) } };\n    const assertion = response;\n    return { ...common, response: { clientDataJSON: base64url(response.clientDataJSON), authenticatorData: base64url(assertion.authenticatorData), signature: base64url(assertion.signature), userHandle: assertion.userHandle ? base64url(assertion.userHandle) : null } };\n}\nexport async function postWithPasskey(route, body = {}) {\n    writable();\n    const name = routeName(route);\n    const canonical = canonicalBody(body);\n    const digestBytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(canonical));\n    const bodyDigest = Array.from(new Uint8Array(digestBytes), byte => byte.toString(16).padStart(2, '0')).join('');\n    const options = publicOptions(await post('passkey/challenge', { route: name, bodyDigest }));\n    let credential;\n    try {\n        const publicKey = {\n            challenge: decode(options.challenge), rpId: 'localhost', userVerification: 'required', timeout: 120_000,\n            allowCredentials: descriptors(options.allowCredentials),\n        };\n        credential = await navigator.credentials.get({ publicKey });\n    }\n    catch {\n        throw new Error('Passkey verification was not completed. Try again.');\n    }\n    if (!credential)\n        throw new Error('Passkey verification was not completed.');\n    let assertion;\n    try {\n        assertion = base64url(new TextEncoder().encode(JSON.stringify(credentialWire(credential, false))).buffer);\n    }\n    catch {\n        throw new Error('Passkey verification was not completed. Try again.');\n    }\n    return request(name, 'POST', canonical, assertion);\n}\n/** Enrollment after the first passkey is itself authorized by a fresh assertion. */\nexport async function registerPasskey() {\n    writable();\n    const options = publicOptions(await (session.passkeys > 0 ? postWithPasskey('passkey/register/options', {}) : post('passkey/register/options', {})));\n    let credential;\n    try {\n        const user = options.user;\n        const publicKey = {\n            ...options, challenge: decode(options.challenge),\n            rp: { id: 'localhost', name: 'keysentry' },\n            user: { id: decode(user.id), name: String(user.name), displayName: String(user.displayName) },\n            excludeCredentials: descriptors(options.excludeCredentials),\n            pubKeyCredParams: options.pubKeyCredParams,\n            authenticatorSelection: { ...options.authenticatorSelection, userVerification: 'required' },\n            attestation: 'none', timeout: 120_000,\n        };\n        credential = await navigator.credentials.create({ publicKey });\n    }\n    catch {\n        throw new Error('Passkey registration was not completed. Try again.');\n    }\n    if (!credential)\n        throw new Error('Passkey registration was not completed.');\n    let wire;\n    try {\n        wire = credentialWire(credential, true);\n    }\n    catch {\n        throw new Error('Passkey registration was not completed. Try again.');\n    }\n    await post('passkey/register/finish', wire);\n    session.passkeys += 1;\n}\n","sha256":"bPf/KZfApHptAHXUaUgJ/OTlyKF229f9wJxUMHx+tFI="},
  "/app/components.js": {"type":"text/javascript; charset=utf-8","body":"import { postWithPasskey } from './api.js';\nexport function button(label, onClick, variant = 'primary') {\n    const control = document.createElement('button');\n    control.type = 'button';\n    control.className = `button ${variant}`;\n    control.textContent = label;\n    if (onClick)\n        control.addEventListener('click', onClick);\n    return control;\n}\nexport function keyTag(key, onOpen) {\n    const tag = button('', onOpen);\n    tag.className = 'key-tag';\n    const provider = document.createElement('span');\n    provider.className = 'key-tag-provider';\n    provider.textContent = key.provider;\n    const hint = document.createElement('code');\n    hint.className = 'key-tag-hint';\n    hint.textContent = key.hint ?? 'Hint unavailable';\n    const metadata = document.createElement('span');\n    metadata.className = 'key-tag-meta';\n    metadata.textContent = [key.copies === undefined ? '' : `${key.copies} ${key.copies === 1 ? 'place' : 'places'}`, key.ageDays === undefined ? '' : `${key.ageDays} ${key.ageDays === 1 ? 'day' : 'days'}`].filter(Boolean).join(' · ');\n    const state = document.createElement('span');\n    state.className = 'key-tag-state';\n    state.textContent = key.state ?? (key.inGitHistory ? 'In git history' : 'Not checked');\n    tag.append(provider, hint, metadata, state);\n    return tag;\n}\nexport function notice(kind, title, text) {\n    const block = document.createElement('section');\n    block.className = `notice notice-${kind}`;\n    const state = document.createElement('span');\n    state.className = 'notice-status';\n    state.textContent = { ok: 'Complete', attention: 'Needs attention', stop: 'Stopped', info: 'Information' }[kind];\n    const heading = document.createElement('h2');\n    heading.textContent = title;\n    const copy = document.createElement('p');\n    copy.textContent = text;\n    block.append(state, heading, copy);\n    return block;\n}\nexport function table(columns, rows, caption = 'Details') {\n    const element = document.createElement('table');\n    element.className = 'data-table';\n    const label = element.createCaption();\n    label.textContent = caption;\n    const head = element.createTHead().insertRow();\n    for (const column of columns) {\n        const cell = document.createElement('th');\n        cell.scope = 'col';\n        cell.textContent = column;\n        head.append(cell);\n    }\n    const body = element.createTBody();\n    for (const row of rows) {\n        const line = body.insertRow();\n        for (const content of row) {\n            const cell = line.insertCell();\n            if (typeof content === 'string')\n                cell.textContent = content;\n            else\n                cell.append(content);\n        }\n    }\n    return element;\n}\nexport function emptyState(text, action) {\n    const block = document.createElement('section');\n    block.className = 'empty-state';\n    const copy = document.createElement('p');\n    copy.textContent = text;\n    block.append(copy);\n    if (action)\n        block.append(button(action.label, action.onClick));\n    return block;\n}\nlet dialogId = 0;\nexport function confirmAction(input) {\n    const previous = document.activeElement;\n    const dialog = document.createElement('dialog');\n    dialog.className = 'confirm-dialog';\n    const heading = document.createElement('h2');\n    heading.id = `confirm-action-${++dialogId}`;\n    heading.textContent = input.title;\n    dialog.setAttribute('aria-labelledby', heading.id);\n    const changes = document.createElement('ul');\n    for (const change of input.changes) {\n        const line = document.createElement('li');\n        line.textContent = change;\n        changes.append(line);\n    }\n    const actions = document.createElement('div');\n    actions.className = 'dialog-actions';\n    return new Promise(resolve => {\n        let completed = false;\n        const finish = (accepted) => {\n            if (completed)\n                return;\n            completed = true;\n            input.signal?.removeEventListener('abort', abort);\n            if (dialog.open)\n                dialog.close();\n            dialog.remove();\n            if (previous instanceof HTMLElement && previous.isConnected)\n                previous.focus();\n            resolve(accepted);\n        };\n        const abort = () => finish(false);\n        const cancel = button('Cancel', () => finish(false), 'secondary');\n        actions.append(cancel, button(input.button, () => finish(true)));\n        dialog.append(heading, changes, actions);\n        dialog.addEventListener('cancel', event => { event.preventDefault(); finish(false); });\n        dialog.addEventListener('close', () => finish(false));\n        if (input.signal?.aborted) {\n            finish(false);\n            return;\n        }\n        input.signal?.addEventListener('abort', abort, { once: true });\n        document.body.append(dialog);\n        dialog.showModal();\n        cancel.focus();\n    });\n}\nlet clipboardClearTimer;\nlet clipboardCopyGeneration = 0;\nconst componentDisposers = new WeakMap();\n/** The router calls this before removing a page, including pages retained by a screen. */\nexport function disposeComponents(root) {\n    if (root instanceof HTMLElement)\n        componentDisposers.get(root)?.();\n    for (const element of root.querySelectorAll('.masked-value'))\n        componentDisposers.get(element)?.();\n}\nasync function clipboardDigest(value) {\n    const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));\n    return Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');\n}\n/** Only a digest is retained by the clear timer, never the copied plaintext. */\nfunction scheduleClipboardClear(expectedDigest, generation, status) {\n    clipboardClearTimer = window.setTimeout(() => {\n        void (async () => {\n            try {\n                let currentDigest;\n                try {\n                    if (navigator.clipboard.readText)\n                        currentDigest = await clipboardDigest(await navigator.clipboard.readText());\n                }\n                catch { /* Clearing can be permitted when reading is unavailable. */ }\n                if (generation === clipboardCopyGeneration && (currentDigest === undefined || expectedDigest === undefined || currentDigest === expectedDigest))\n                    await navigator.clipboard.writeText('');\n            }\n            catch {\n                status.textContent = 'Clipboard clearing was unavailable. Clear it when you are done.';\n            }\n        })();\n    }, 30_000);\n}\n/** Reveal is always an explicit confirmation followed by the shared passkey request. */\nexport function maskedValue(input = {}) {\n    const block = document.createElement('div');\n    block.className = 'masked-value';\n    const output = document.createElement('span');\n    output.className = 'masked-value-output';\n    output.textContent = 'Hidden';\n    output.setAttribute('aria-live', 'polite');\n    const actions = document.createElement('div');\n    actions.className = 'value-actions';\n    const status = document.createElement('span');\n    status.setAttribute('role', 'status');\n    let value = '';\n    let disposed = false;\n    let revealGeneration = 0;\n    let confirmation;\n    const hide = () => { ++revealGeneration; confirmation?.abort(); value = ''; output.textContent = 'Hidden'; status.textContent = ''; reveal.disabled = false; actions.replaceChildren(reveal); };\n    const copy = button('Copy', () => {\n        if (disposed)\n            return;\n        const copied = value;\n        status.textContent = 'Copying.';\n        void (async () => {\n            try {\n                await navigator.clipboard.writeText(copied);\n                const generation = ++clipboardCopyGeneration;\n                if (clipboardClearTimer !== undefined)\n                    window.clearTimeout(clipboardClearTimer);\n                let digest;\n                try {\n                    digest = await clipboardDigest(copied);\n                }\n                catch { /* Still attempt to clear if digest support becomes unavailable. */ }\n                if (generation !== clipboardCopyGeneration)\n                    return;\n                status.textContent = 'Copied. keysentry will try to clear the clipboard in 30 seconds.';\n                scheduleClipboardClear(digest, generation, status);\n            }\n            catch {\n                status.textContent = 'Copy was unavailable. Try again.';\n            }\n        })();\n    }, 'secondary');\n    const reveal = button('Reveal', () => {\n        if (disposed || reveal.disabled)\n            return;\n        const generation = ++revealGeneration;\n        confirmation = new AbortController();\n        reveal.disabled = true;\n        void (async () => {\n            try {\n                if (!await confirmAction({ title: input.label ?? 'Reveal value', changes: ['keysentry will show this value in this browser until you hide it or leave the page.'], button: 'Reveal value', signal: confirmation?.signal }))\n                    return;\n                if (disposed || generation !== revealGeneration)\n                    return;\n                const result = await postWithPasskey(input.route ?? 'reveal', input.body ?? {});\n                if (disposed || generation !== revealGeneration) {\n                    result.value = '';\n                    return;\n                }\n                if (typeof result.value !== 'string')\n                    throw new Error();\n                value = result.value;\n                output.textContent = value;\n                status.textContent = '';\n                actions.replaceChildren(copy, button('Hide', hide, 'secondary'));\n            }\n            catch {\n                if (!disposed && generation === revealGeneration)\n                    status.textContent = 'The value could not be revealed. Try again.';\n            }\n            finally {\n                if (!disposed && generation === revealGeneration)\n                    reveal.disabled = false;\n            }\n        })();\n    }, 'secondary');\n    const pagehide = () => hide();\n    window.addEventListener('pagehide', pagehide);\n    componentDisposers.set(block, () => {\n        if (disposed)\n            return;\n        hide();\n        disposed = true;\n        actions.replaceChildren();\n        window.removeEventListener('pagehide', pagehide);\n        componentDisposers.delete(block);\n    });\n    actions.append(reveal);\n    block.append(output, actions, status);\n    return block;\n}\n","sha256":"q8bHXFCjZLkpy2jDvj19JQFk0eYIYimLjBSVPZqENWY="},
  "/": {"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <meta name=\"color-scheme\" content=\"light dark\">\n    <title>keysentry</title>\n    <link rel=\"stylesheet\" href=\"/app/styles.css\">\n    <link rel=\"stylesheet\" href=\"/app/screens-a.css\">\n    <link rel=\"stylesheet\" href=\"/app/screens-b.css\">\n    <script type=\"module\" src=\"/app/main.js\"></script>\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <noscript>Enable JavaScript to use the local keysentry dashboard.</noscript>\n  </body>\n</html>\n","sha256":"bt1Qxnz6udeY1p5QTUaf8Nw1nY4pn0DYm78hIIoXEQo="},
  "/app/main.js": {"type":"text/javascript; charset=utf-8","body":"import { fetchSession, registerPasskey } from './api.js';\nimport { button, emptyState, notice } from './components.js';\nimport { createRouter } from './router.js';\nimport { registerScreensA } from './screens/a.js';\nimport { registerScreensB } from './screens/b.js';\nconst pages = [\n    ['home', 'Overview', 'Overview'], ['keys', 'Keys', 'Your keys'], ['connect', 'Connect', 'Connect a platform'],\n    ['rotate', 'Rotate', 'Rotate keys'], ['autopilot', 'Autopilot', 'Autopilot'], ['activity', 'Activity', 'Activity'],\n    ['notifications', 'Notifications', 'Notifications'], ['approvals', 'Approvals', 'Approvals'], ['settings', 'Settings', 'Settings'],\n    ['card', 'Readiness card', 'Readiness card'],\n];\nfunction link(text, route) {\n    const anchor = document.createElement('a');\n    anchor.href = `#/${route}`;\n    anchor.textContent = text;\n    return anchor;\n}\nexport async function boot(root) {\n    const session = await fetchSession();\n    const shell = document.createElement('div');\n    shell.className = 'app-shell';\n    const skip = document.createElement('a');\n    skip.className = 'skip-link';\n    skip.href = '#main-content';\n    skip.textContent = 'Skip to content';\n    const header = document.createElement('header');\n    header.className = 'app-header';\n    const brand = link('keysentry', 'home');\n    brand.className = 'app-brand';\n    const headerLinks = document.createElement('div');\n    headerLinks.className = 'app-header-links';\n    headerLinks.append(link('What keysentry can access', 'access'), link('Network', 'network'));\n    header.append(brand, headerLinks);\n    const body = document.createElement('div');\n    body.className = 'app-body';\n    const nav = document.createElement('nav');\n    nav.className = 'app-nav';\n    nav.setAttribute('aria-label', 'Main navigation');\n    for (const [route, label] of pages)\n        nav.append(link(label, route));\n    const content = document.createElement('div');\n    const main = document.createElement('main');\n    main.className = 'page';\n    main.id = 'main-content';\n    skip.addEventListener('click', event => { event.preventDefault(); main.querySelector('h1')?.focus(); });\n    if (session.readOnly) {\n        const readOnly = notice('info', 'Read-only', 'This dashboard is read-only because it was opened by an automated tool or with --read-only. To make changes, run keysentry ui in your own terminal.');\n        readOnly.classList.add('read-only-notice');\n        // The router replaces page children on navigation; keep this notice below its heading.\n        new MutationObserver(() => {\n            const heading = main.querySelector('h1');\n            if (heading && heading.nextSibling !== readOnly)\n                heading.after(readOnly);\n        }).observe(main, { childList: true });\n    }\n    else if (session.passkeys === 0) {\n        const enrollment = notice('info', 'Register a passkey', 'Changes require a passkey with user verification. Register one on this device before making a change.');\n        const status = document.createElement('p');\n        status.setAttribute('role', 'status');\n        const control = button('Register passkey', () => { control.disabled = true; void registerPasskey().then(() => { session.passkeys++; enrollment.replaceChildren(notice('ok', 'Passkey registered', 'Your passkey will be requested when you choose a change.')); }).catch(() => { status.textContent = 'Passkey registration was not completed. Try again.'; }).finally(() => { control.disabled = false; }); });\n        enrollment.append(control, status);\n        content.append(enrollment);\n    }\n    content.append(main);\n    body.append(nav, content);\n    shell.append(skip, header, body);\n    root.replaceChildren(shell);\n    const router = createRouter(main, {}, route => {\n        for (const anchor of shell.querySelectorAll('a[href^=\"#/\"]')) {\n            if (anchor.hash === `#/${route}`)\n                anchor.setAttribute('aria-current', 'page');\n            else\n                anchor.removeAttribute('aria-current');\n        }\n    });\n    for (const [path, , title] of [...pages, ['access', 'Access', 'What keysentry can access'], ['network', 'Network', 'Network']]) {\n        router.register(path, { title, render: () => emptyState(path === 'home' ? 'Start with your keys to review the next steps for this project.' : 'Return to the overview to choose the next step for this project.', { label: path === 'home' ? 'See your keys' : 'Open overview', onClick: () => router.navigate(path === 'home' ? 'keys' : 'home') }) });\n    }\n    // Real screens replace the placeholders above (tasks 6a and 6b each own one registration module).\n    registerScreensA(router, session);\n    registerScreensB(router, session);\n    await router.start();\n    return { session, router, destroy() { router.stop(); root.replaceChildren(); } };\n}\nfunction start() {\n    const root = document.getElementById('app');\n    if (root)\n        void boot(root).catch(() => { root.replaceChildren(notice('info', 'Open keysentry again', 'Open keysentry from your terminal with keysentry ui.')); });\n}\nif (document.readyState === 'loading')\n    document.addEventListener('DOMContentLoaded', start, { once: true });\nelse\n    start();\n","sha256":"zf+/sxOkf6jeMfh/I5adjJ/nWIOSUKiUEUKxD/IFvjs="},
  "/app/router.js": {"type":"text/javascript; charset=utf-8","body":"import { disposeComponents, emptyState } from './components.js';\n/** Screen renderers return page content; the router owns the page heading and focus. */\nexport function createRouter(outlet, initial = {}, onNavigate) {\n    const routes = new Map(Object.entries(initial));\n    let generation = 0;\n    let started = false;\n    let lastPath;\n    const path = () => location.hash.replace(/^#\\/?/, '').split('?')[0] || 'home';\n    const refresh = async () => {\n        const current = ++generation;\n        disposeComponents(outlet);\n        const selected = path();\n        lastPath = selected;\n        const route = routes.get(selected);\n        const heading = document.createElement('h1');\n        heading.className = 'page-heading';\n        heading.tabIndex = -1;\n        heading.textContent = route?.title ?? 'Page not found';\n        let content;\n        try {\n            content = route ? await route.render() : emptyState('Choose a page from the navigation to continue.', { label: 'Open overview', onClick: () => router.navigate('home') });\n        }\n        catch {\n            content = emptyState('This page could not be opened. Try again.', { label: 'Try again', onClick: () => { void refresh(); } });\n        }\n        if (current !== generation) {\n            if (content instanceof Element || content instanceof DocumentFragment)\n                disposeComponents(content);\n            return;\n        }\n        outlet.replaceChildren(heading, content);\n        document.title = `${heading.textContent} · keysentry`;\n        heading.focus();\n        onNavigate?.(selected);\n    };\n    const changed = () => { if (path() !== lastPath)\n        void refresh(); };\n    const router = {\n        register(key, route) { routes.set(key.replace(/^#\\/?/, ''), route); },\n        async start() { if (!started) {\n            started = true;\n            window.addEventListener('hashchange', changed);\n            await refresh();\n        } },\n        stop() { started = false; generation++; disposeComponents(outlet); window.removeEventListener('hashchange', changed); },\n        navigate(key) { const next = key.replace(/^#\\/?/, ''); if (path() === next)\n            void refresh();\n        else\n            location.hash = `#/${next}`; },\n        refresh,\n    };\n    return router;\n}\n","sha256":"35kX+9vsm79nguX4B2iWVr6NwZSW1bavgl9Wc2rEh5g="},
  "/app/screens-a.css": {"type":"text/css; charset=utf-8","body":".screen-a { min-width: 0; }\n.screen-a-section + .screen-a-section { margin-top: var(--space-8); }\n.screen-a-section { margin-block: var(--space-6); }\n.screen-a-muted { color: var(--muted); }\n.screen-a-links { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-4) var(--space-6); margin-block: var(--space-6); }\n.screen-a-state { font-weight: 600; }\n.screen-a .state-ok, .screen-a .key-tag[data-state=\"ok\"] .key-tag-state { color: var(--ok); }\n.screen-a .state-attention, .screen-a .key-tag[data-state=\"attention\"] .key-tag-state { color: var(--attention); }\n.screen-a .state-stop, .screen-a .key-tag[data-state=\"stop\"] .key-tag-state { color: var(--stop); }\n.screen-a-filters { display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--space-4); margin-block: var(--space-6); }\n.screen-a-filter { display: flex; flex-wrap: wrap; gap: var(--space-2); min-width: 0; margin: 0; padding: 0; border: 0; }\n.screen-a-filter legend { margin-bottom: var(--space-2); font-weight: 600; }\n.screen-a-filter .button { font-weight: 400; }\n.screen-a-filter .button[aria-pressed=\"true\"] { color: var(--surface); background: var(--ink); border-color: var(--ink); }\n.screen-a-cabinet { display: grid; align-items: start; gap: var(--space-6); }\n.screen-a-cabinet.has-detail { grid-template-columns: minmax(240px, 1fr) minmax(320px, 1fr); }\n.screen-a-cabinet .key-grid { grid-template-columns: repeat(auto-fill, minmax(min(240px, 100%), 1fr)); }\n.screen-a-key-panel { min-width: 0; padding: var(--space-6); border: 1px solid var(--line); border-radius: var(--radius-dialog); background: var(--surface); box-shadow: 0 12px 32px rgb(0 0 0 / 0.18); }\n.screen-a-key-panel > code { display: block; overflow-wrap: anywhere; margin-bottom: var(--space-4); }\n.screen-a-key-panel .screen-a-state { margin-top: var(--space-4); }\n.screen-a-key-panel .table-scroll { margin-block: var(--space-6); }\n.screen-a-token { max-width: 72ch; padding-block: var(--space-4); border-top: 1px solid var(--line); }\n.screen-a-token h3 code { overflow-wrap: anywhere; }\n.screen-a-token-form { display: grid; gap: var(--space-4); max-width: 40rem; padding-block: var(--space-6); }\n.screen-a-token-form label { display: grid; gap: var(--space-2); }\n.screen-a-token-form .button { justify-self: start; }\n.screen-a-token-form [role=\"status\"]:empty { display: none; }\n.screen-a-token-form p { margin-bottom: 0; }\n.screen-a-check { padding-block: var(--space-4); border-top: 1px solid var(--line); }\n.screen-a-check p:last-child { margin-bottom: 0; }\n.screen-a-check-status { font-weight: 600; }\n.screen-a-section li, .overview-screen li { margin-block: var(--space-2); overflow-wrap: anywhere; }\n.screen-a .data-table td { overflow-wrap: anywhere; }\n.screen-a-access .notice + .notice { margin-top: var(--space-4); }\n@media (max-width: 1100px) {\n  .screen-a-cabinet.has-detail { grid-template-columns: minmax(0, 1fr); }\n}\n","sha256":"MBDBBwgFpztK3aO6wvNTyZJx20TShdL+NO5F1pXqd/Y="},
  "/app/screens-b.css": {"type":"text/css; charset=utf-8","body":".screen-b { display: grid; gap: var(--space-6); min-width: 0; }\n.screen-b > p { margin-bottom: 0; }\n.b-section { min-width: 0; padding-block: var(--space-4); border-top: 1px solid var(--line); }\n.b-section > :last-child { margin-bottom: 0; }\n.b-form { max-width: 72ch; }\n.b-field { display: flex; flex-direction: column; gap: var(--space-2); max-width: 72ch; margin-block: var(--space-3); }\n.b-field:has(input[type=\"checkbox\"]) { flex-direction: row-reverse; justify-content: flex-end; align-items: flex-start; gap: var(--space-3); }\n.b-field input[type=\"checkbox\"] { flex-shrink: 0; width: 20px; height: 20px; margin-top: var(--space-1); accent-color: var(--brass); }\n.b-field > input:not([type=\"checkbox\"]), .b-field > select { width: 100%; }\n.b-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3); margin-block: var(--space-4); }\n.b-feedback:empty { display: none; }\n.screen-b fieldset { min-width: 0; margin: 0; padding: var(--space-4) var(--space-6); border: 1px solid var(--control-line); border-radius: var(--radius-control); }\n.screen-b legend { padding-inline: var(--space-2); font-weight: 600; }\n.b-countdown { display: flex; align-items: center; gap: var(--space-3); margin-block: var(--space-4); }\n.b-grace-ring { width: 48px; height: 48px; flex-shrink: 0; transform: rotate(-90deg); }\n.b-grace-ring circle { fill: none; stroke: var(--brass); stroke-width: 3; }\n.b-grace-ring.counting circle { transition: stroke-dashoffset 1s linear; }\n.b-readiness-card { display: block; width: 100%; max-width: 960px; height: auto; border: 1px solid var(--line); border-radius: var(--radius-control); background: var(--surface); }\n.b-cap-row { display: flex; align-items: flex-end; flex-wrap: wrap; gap: var(--space-3); }\n.b-cap-row > .b-field { flex: 1 1 160px; }\n.b-cap-row > .button { margin-bottom: var(--space-3); }\n@media (prefers-reduced-motion: reduce) { .b-grace-ring.counting circle { transition: none; } }\n@media (max-width: 480px) { .b-actions > .button { width: 100%; } .screen-b fieldset { padding: var(--space-3); } }\n","sha256":"vg3BjL57Jg/oUSGNvG0ztSKXEz6gyzr93Ot2LOSWmD8="},
  "/app/screens/a.js": {"type":"text/javascript; charset=utf-8","body":"import { renderHome } from './home.js';\nimport { renderKeys } from './keys.js';\nimport { renderConnect } from './connect.js';\nimport { renderAccess } from './access.js';\nimport { renderNetwork } from './network.js';\nexport function registerScreensA(router, session) {\n    router.register('home', { title: 'Overview', render: renderHome });\n    router.register('keys', { title: 'Your keys', render: () => renderKeys(session) });\n    router.register('connect', { title: 'Connect a platform', render: () => renderConnect(session) });\n    router.register('access', { title: 'What keysentry can access', render: renderAccess });\n    router.register('network', { title: 'Network', render: renderNetwork });\n}\n","sha256":"I+iN1XDnVfvpTyUHRWl+exfrZszK3TFQO1NJifOkeD0="},
  "/app/screens/access.js": {"type":"text/javascript; charset=utf-8","body":"import { get } from '../api.js';\nimport { emptyState, notice } from '../components.js';\n/** Doctor reports describe permissions and checks; no token values are requested. */\nexport async function renderAccess() {\n    const { items } = await get('access');\n    const page = document.createElement('div');\n    page.className = 'screen-a-access';\n    const introduction = document.createElement('p');\n    introduction.textContent = 'Review what your tokens allow, how keysentry uses them, and any changes the checks recommend.';\n    page.append(introduction);\n    if (items.length === 0) {\n        page.append(emptyState('No access checks are available yet. Connect a platform to review its token permissions.'));\n        const link = document.createElement('a');\n        link.href = '#/connect';\n        link.textContent = 'Connect a platform';\n        page.append(link);\n        return page;\n    }\n    const groups = new Map();\n    for (const item of items) {\n        const group = groups.get(item.area) ?? [];\n        group.push(item);\n        groups.set(item.area, group);\n    }\n    const kinds = { ok: 'ok', warn: 'attention', fail: 'stop', info: 'info' };\n    for (const [area, checks] of groups) {\n        const section = document.createElement('section');\n        section.className = 'screen-a-section';\n        const heading = document.createElement('h2');\n        heading.textContent = area;\n        section.append(heading);\n        for (const item of checks) {\n            const check = notice(kinds[item.status], item.title, item.detail);\n            const title = check.querySelector('h2');\n            const nestedTitle = document.createElement('h3');\n            nestedTitle.textContent = item.title;\n            title?.replaceWith(nestedTitle);\n            if (item.fix) {\n                const fix = document.createElement('p');\n                fix.className = 'screen-a-fix';\n                fix.textContent = `Next step: ${item.fix}`;\n                check.append(fix);\n            }\n            section.append(check);\n        }\n        page.append(section);\n    }\n    return page;\n}\n","sha256":"390CQH9heYz49EFfRNBT+nJUBF/mmUZG5ZNVPBAGJxk="},
  "/app/screens/activity.js": {"type":"text/javascript; charset=utf-8","body":"import { get, post } from '../api.js';\nimport { emptyState, notice, table } from '../components.js';\nimport { actions, dateTime, download, el, field, input, lifetime, paragraph, scrollTable, section, status, taskButton } from './components-b.js';\nexport async function renderActivity(_session) {\n    const data = await get('activity');\n    const root = el('div', undefined, 'screen-b');\n    const scope = lifetime(root);\n    const feedback = status();\n    const audit = notice(data.verify.ok ? 'ok' : 'attention', data.verify.ok ? 'Audit check passed' : 'Audit needs review', data.verify.ok ? 'The recorded audit entries passed verification.' : data.verify.problem ?? 'The audit could not be verified. Review the local audit log.');\n    const timeline = el('div');\n    const id = input('id', 'text', new URLSearchParams(location.hash.split('?')[1]).get('id') ?? '');\n    id.required = true;\n    const load = taskButton('Timeline', feedback, async () => {\n        const selected = id.value.trim();\n        if (!selected) {\n            feedback.textContent = 'Enter a plan or wave ID.';\n            return;\n        }\n        const result = await post('timeline', { id: selected });\n        if (scope.signal.aborted)\n            return;\n        const exportButton = taskButton('Download Markdown', feedback, async () => { download(new Blob([result.markdown], { type: 'text/markdown;charset=utf-8' }), 'keysentry-timeline.md'); });\n        timeline.replaceChildren(section('Timeline', result.events.length ? scrollTable(table(['When', 'Event', 'Details'], result.events.map(event => [dateTime(event.at), event.kind, event.summary]), 'Incident timeline')) : emptyState('No events recorded for this plan or wave.'), actions(exportButton)));\n    });\n    const form = el('form', undefined, 'b-form');\n    form.append(field('Plan or wave ID', id), actions(load));\n    form.addEventListener('submit', event => { event.preventDefault(); load.click(); });\n    root.append(audit, section('Audit entries', data.entries.length ? scrollTable(table(['When', 'Event', 'Details'], data.entries.map(entry => [dateTime(entry.at), entry.kind, entry.summary]), 'Recent audit entries')) : emptyState('No audit entries yet.')), section('View a timeline', paragraph('Choose a plan or wave to review its events and download a Markdown copy.'), form), feedback, timeline);\n    scope.onMount(() => { if (id.value)\n        load.click(); });\n    return root;\n}\n","sha256":"njLQVRXvYwbTAbm7OnXK+ooFxQrG2Yr226E6k2lVKdU="},
  "/app/screens/approvals.js": {"type":"text/javascript; charset=utf-8","body":"import { get, postWithPasskey } from '../api.js';\nimport { confirmAction, emptyState } from '../components.js';\nimport { actions, dateTime, el, lifetime, message, paragraph, section, status, taskButton } from './components-b.js';\nexport async function renderApprovals(session) {\n    const { pending } = await get('approvals');\n    const root = el('div', undefined, 'screen-b');\n    const scope = lifetime(root);\n    const feedback = status();\n    root.append(paragraph('Review the exact action before approving or dismissing it. Each choice needs your passkey.'), feedback);\n    if (!pending.length)\n        root.append(emptyState('No approvals waiting. New requests will appear here when a decision is needed.'));\n    const expiries = [];\n    for (const item of pending) {\n        const deadline = item.expiresAt ? Date.parse(item.expiresAt) : Infinity;\n        let completed = false;\n        const expired = () => !Number.isFinite(deadline) && deadline !== Infinity || Date.now() >= deadline;\n        const state = paragraph(expired() ? 'Expired' : 'Pending');\n        const block = section(item.summary, paragraph(`${item.kind} · From ${item.source} · Created ${dateTime(item.createdAt)}.${item.expiresAt ? ` Expires ${dateTime(item.expiresAt)}.` : ''}`), state);\n        const decide = async (decision) => {\n            if (expired()) {\n                state.textContent = 'Expired';\n                return;\n            }\n            const label = decision === 'approve' ? 'Approve' : 'Dismiss';\n            if (!await confirmAction({ title: `${label} request`, changes: [item.summary, decision === 'approve' ? 'keysentry will approve this one action.' : 'keysentry will dismiss this request.'], button: label, signal: scope.signal }) || scope.signal.aborted)\n                return;\n            if (expired()) {\n                state.textContent = 'Expired';\n                return;\n            }\n            const result = await postWithPasskey(`approvals/${decision}`, { id: item.id });\n            if (scope.signal.aborted)\n                return;\n            completed = true;\n            state.textContent = decision === 'approve' ? 'Approved' : 'Dismissed';\n            controls.remove();\n            message(feedback, state.textContent, decision === 'approve' ? result.result ?? 'This action was approved.' : 'This request was dismissed.', 'ok');\n        };\n        const approve = taskButton('Approve', feedback, async () => { approve.disabled = true; dismiss.disabled = true; try {\n            await decide('approve');\n        }\n        finally {\n            if (controls.isConnected)\n                dismiss.disabled = session.readOnly || expired();\n        } }, () => session.readOnly || expired() || completed);\n        const dismiss = taskButton('Dismiss', feedback, async () => { approve.disabled = true; dismiss.disabled = true; try {\n            await decide('dismiss');\n        }\n        finally {\n            if (controls.isConnected)\n                approve.disabled = session.readOnly || expired();\n        } }, () => session.readOnly || expired() || completed);\n        const controls = actions(approve, dismiss);\n        block.append(controls);\n        root.append(block);\n        if (!expired() && deadline !== Infinity)\n            expiries.push({ deadline, controls: [approve, dismiss], label: state, pending: () => !completed });\n    }\n    let timer;\n    const check = () => { for (const item of expiries)\n        if (item.pending() && Date.now() >= item.deadline) {\n            item.label.textContent = 'Expired';\n            for (const control of item.controls)\n                control.disabled = true;\n        } };\n    scope.onMount(() => { if (expiries.length)\n        timer = window.setInterval(check, 1_000); });\n    scope.onDispose(() => { if (timer !== undefined)\n        window.clearInterval(timer); });\n    return root;\n}\n","sha256":"wWzAcMQ1XFvuu1P3b8CfnQN5WL5YVmt6SJhHEfK8jJM="},
  "/app/screens/autopilot.js": {"type":"text/javascript; charset=utf-8","body":"import { get, post, postWithPasskey } from '../api.js';\nimport { confirmAction, emptyState, table } from '../components.js';\nimport { actions, dateTime, el, field, input, lifetime, list, message, numberInput, paragraph, scrollTable, section, status, taskButton, validNumber } from './components-b.js';\n// Keep unfinished arm/disarm ordering across route changes within this session.\nconst sessions = new WeakMap();\nfunction coordinationFor(session) {\n    let coordination = sessions.get(session);\n    if (!coordination) {\n        coordination = { offGeneration: 0, turningOff: false, listeners: new Set() };\n        sessions.set(session, coordination);\n    }\n    return coordination;\n}\nconst platforms = { railway: 'Railway', fly: 'Fly', vercel: 'Vercel', render: 'Render', 'github-actions': 'GitHub Actions', dotenv: 'Local files' };\nexport async function renderAutopilot(session) {\n    const [initial, eligibility] = await Promise.all([get('autopilot'), get('autopilot/eligibility')]);\n    const root = el('div', undefined, 'screen-b');\n    const scope = lifetime(root);\n    const feedback = status();\n    let state = initial;\n    let lastDrillAt = eligibility.lastDrillAt;\n    const coordination = coordinationFor(session);\n    const notify = (updated) => { for (const listener of coordination.listeners)\n        listener(updated); };\n    const stateText = paragraph('');\n    const stateNotes = el('div');\n    const describe = () => {\n        if (coordination.turningOff)\n            stateText.textContent = 'Autopilot is turning off while an earlier request finishes.';\n        else if (state.state === 'armed' && state.plan) {\n            const expiry = new Date(state.plan.expiresAt);\n            const until = Number.isFinite(expiry.getTime()) ? expiry.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : 'its expiry';\n            stateText.textContent = `Autopilot is armed for ${state.plan.keys} ${state.plan.keys === 1 ? 'key' : 'keys'} on ${state.plan.hosts.map(host => platforms[host] ?? host).join(' and ')} until ${until}.`;\n        }\n        else\n            stateText.textContent = { off: 'Autopilot is off.', armed: 'Autopilot is armed; scope details are unavailable.', 'alert-only': 'Autopilot is in alert-only mode.', disarmed: 'Autopilot is disarmed.' }[state.state];\n        stateNotes.replaceChildren(...(state.reasons.length ? [list(state.reasons)] : []));\n        if (state.needsRefresh)\n            stateNotes.append(paragraph('The armed plan needs a refresh. Review the key choices and run a drill before arming again.'));\n    };\n    describe();\n    const chosen = new Map();\n    const adoptions = new Map();\n    const rows = eligibility.eligible.map(key => {\n        const choose = input(key.id, 'checkbox');\n        choose.disabled = session.readOnly;\n        chosen.set(key.id, choose);\n        const identity = field(`${key.provider} · ${key.hint ?? 'Hint unavailable'}`, choose);\n        choose.addEventListener('change', () => updateArm());\n        let consent = el('span', 'No adoption needed');\n        if (key.needsAdoption) {\n            const adopt = input(`adopt-${key.id}`, 'checkbox');\n            adopt.disabled = session.readOnly;\n            adoptions.set(key.id, adopt);\n            adopt.addEventListener('change', () => { if (adopt.checked)\n                choose.checked = true; updateArm(); });\n            consent = field('This rotates the key now so keysentry can rotate it automatically later', adopt);\n        }\n        return [identity, key.needsAdoption ? 'Needs adoption' : 'Eligible', consent];\n    });\n    rows.push(...eligibility.ineligible.map(key => [key.hint ?? 'Hint unavailable', 'Not eligible', key.reason]));\n    const grace = numberInput('graceMinutes', state.plan?.graceMinutes ?? 15, 0, Math.floor(Number.MAX_SAFE_INTEGER / 60));\n    const maxServices = numberInput('maxServices', 10, 1);\n    const validDays = numberInput('validDays', 90, 1, 365);\n    for (const control of [grace, maxServices, validDays])\n        control.disabled = session.readOnly;\n    const recent = () => { const at = Date.parse(lastDrillAt ?? ''); const age = Date.now() - at; return Number.isFinite(at) && age >= 0 && age < 86_400_000; };\n    const drillNote = paragraph('');\n    let expiryTimer;\n    const arm = taskButton('Arm autopilot', feedback, async () => {\n        const armGeneration = coordination.offGeneration;\n        const clusterIds = [...chosen].filter(([, choice]) => choice.checked).map(([id]) => id);\n        const adopt = [...adoptions].filter(([id, choice]) => choice.checked && chosen.get(id)?.checked).map(([id]) => id);\n        const graceMinutes = validNumber(grace, 0, Math.floor(Number.MAX_SAFE_INTEGER / 60), false);\n        const maximum = validNumber(maxServices, 1);\n        const days = validNumber(validDays, 1, 365);\n        if (!recent()) {\n            updateArm();\n            message(feedback, 'Run a drill first', 'Arming needs a drill from the last 24 hours.', 'attention');\n            return;\n        }\n        if (!clusterIds.length || clusterIds.some(id => adoptions.has(id) && !adopt.includes(id))) {\n            message(feedback, 'Review key choices', 'Choose at least one key. For each key that needs adoption, agree to rotate it now or leave it unselected.', 'attention');\n            return;\n        }\n        if (graceMinutes === null || maximum === null || days === null) {\n            message(feedback, 'Check the numbers', 'Use a nonnegative grace period, a positive whole number of services, and 1 to 365 days.', 'attention');\n            return;\n        }\n        const changes = [`keysentry will arm autopilot for ${clusterIds.length} ${clusterIds.length === 1 ? 'key' : 'keys'} for ${days} days, with up to ${maximum} services per wave and ${graceMinutes} minutes of grace.`];\n        for (const id of adopt) {\n            const key = eligibility.eligible.find(item => item.id === id);\n            changes.push(`This rotates ${key.provider} ${key.hint ?? '(hint unavailable)'} now so keysentry can rotate it automatically later.`);\n        }\n        if (!await confirmAction({ title: 'Arm autopilot', changes, button: 'Arm autopilot', signal: scope.signal }) || scope.signal.aborted || armGeneration !== coordination.offGeneration || coordination.turningOff)\n            return;\n        // The confirmation and passkey can take time; the server also checks the last drill.\n        if (!recent()) {\n            updateArm();\n            message(feedback, 'Run another drill', 'The last drill is now more than 24 hours old.', 'attention');\n            return;\n        }\n        const pending = postWithPasskey('autopilot/arm', { clusterIds, adopt, graceMinutes, maxServices: maximum, validDays: days });\n        coordination.arming = pending;\n        notify();\n        let result;\n        try {\n            result = await pending;\n        }\n        finally {\n            if (coordination.arming === pending)\n                coordination.arming = undefined;\n            notify();\n        }\n        if (armGeneration !== coordination.offGeneration)\n            return;\n        if (!scope.signal.aborted)\n            message(feedback, result.refused.length ? 'Review arming result' : 'Autopilot armed', result.refused.length ? result.refused.map(item => item.reason).join(' ') : `Armed until ${dateTime(result.expiresAt)}.`, result.refused.length ? 'attention' : 'ok');\n        if (coordination.listeners.size) {\n            const updated = await get('autopilot');\n            if (armGeneration === coordination.offGeneration)\n                notify(updated);\n        }\n    }, () => session.readOnly || coordination.turningOff || !!coordination.arming || !recent() || ![...chosen.values()].some(choice => choice.checked));\n    const updateArm = () => { arm.disabled = session.readOnly || coordination.turningOff || !!coordination.arming || !recent() || ![...chosen.values()].some(choice => choice.checked); drillNote.textContent = recent() ? `Last drill: ${dateTime(lastDrillAt)}. Arming needs a drill from the last 24 hours.` : 'Run a drill before arming. The drill must be from the last 24 hours.'; };\n    let disarmControl;\n    const changed = (updated) => { if (updated)\n        state = updated; describe(); updateArm(); if (disarmControl)\n        disarmControl.disabled = coordination.turningOff; };\n    coordination.listeners.add(changed);\n    scope.onDispose(() => coordination.listeners.delete(changed));\n    const scheduleExpiry = () => {\n        if (expiryTimer !== undefined)\n            window.clearTimeout(expiryTimer);\n        if (recent())\n            expiryTimer = window.setTimeout(updateArm, Math.max(1, Date.parse(lastDrillAt) + 86_400_000 - Date.now()));\n    };\n    scope.onDispose(() => { if (expiryTimer !== undefined)\n        window.clearTimeout(expiryTimer); });\n    scope.onMount(scheduleExpiry);\n    const drill = taskButton('Run a drill', feedback, async () => {\n        const result = await post('drill', {});\n        if (scope.signal.aborted)\n            return;\n        lastDrillAt = new Date().toISOString();\n        updateArm();\n        scheduleExpiry();\n        message(feedback, 'Drill complete', `Readiness ${result.score}/100. ${result.reasons.join(' ')}`, 'ok');\n    });\n    const disarm = taskButton('Turn off autopilot', feedback, async () => {\n        if (!await confirmAction({ title: 'Turn off autopilot', changes: ['keysentry will stop starting automatic rotations. Rotations already in progress keep their current status.'], button: 'Turn off autopilot', signal: scope.signal }) || scope.signal.aborted)\n            return;\n        ++coordination.offGeneration;\n        coordination.turningOff = true;\n        notify();\n        const pending = coordination.arming;\n        try {\n            let result = await post('autopilot/disarm', {});\n            if (pending) {\n                if (!scope.signal.aborted) {\n                    stateText.textContent = 'Autopilot is turning off while an earlier arming request finishes.';\n                    message(feedback, 'Turning off autopilot', 'The current plan is disarmed. keysentry will turn it off again when the earlier arming request finishes.');\n                }\n                // The passkey helper cannot cancel an assertion already in flight. Disarm immediately,\n                // then repeat after that exact request settles so an earlier arm cannot be the last write.\n                await pending.catch(() => { });\n                result = await post('autopilot/disarm', {});\n            }\n            state = { ...state, state: result.state, reasons: [], needsRefresh: false };\n            notify(state);\n            if (!scope.signal.aborted)\n                message(feedback, 'Autopilot disarmed', 'Automatic rotations are turned off.', 'ok');\n        }\n        finally {\n            coordination.turningOff = false;\n            notify();\n        }\n    }, () => coordination.turningOff);\n    disarmControl = disarm;\n    updateArm();\n    root.append(stateText, stateNotes, paragraph(`Last successful notification: ${dateTime(state.lastNotificationAt)}.`), section('Keys for autopilot', rows.length ? scrollTable(table(['Key', 'Eligibility', 'Reason or adoption choice'], rows, 'Autopilot eligibility')) : emptyState('No eligible keys yet. Connect a platform and scan your keys.')), section('Arm autopilot', paragraph('A drill checks readiness without changing keys. Arming allows automatic rotations within the chosen scope. Adoption performs a rotation now for each key you select for adoption.'), drillNote, field('Grace period (minutes)', grace), field('Maximum services per wave', maxServices), field('Plan validity (days)', validDays), actions(drill, arm, disarm)), feedback, section('Waves', state.waves.length ? scrollTable(table(['Incident', 'Status', 'Deadline', 'Timeline'], state.waves.map(wave => {\n        const link = el('a', 'Timeline');\n        link.href = `#activity?id=${encodeURIComponent(wave.id)}`;\n        return [wave.incident, wave.status, dateTime(wave.deadline), link];\n    }), 'Autopilot waves')) : emptyState('No autopilot waves yet.')));\n    return root;\n}\n","sha256":"ejDa6akvWAYZ6P4ktZtxnJn5nDmIveu8TZAeA3QuXeE="},
  "/app/screens/b.js": {"type":"text/javascript; charset=utf-8","body":"import { renderRotate } from './rotate.js';\nimport { renderAutopilot } from './autopilot.js';\nimport { renderActivity } from './activity.js';\nimport { renderNotifications } from './notifications.js';\nimport { renderApprovals } from './approvals.js';\nimport { renderSettings } from './settings.js';\nimport { renderCard } from './card.js';\nimport { disposeScreen } from './components-b.js';\nexport function registerScreensB(router, session) {\n    let generation = 0;\n    let current;\n    // The existing shell exposes stop(), but no general screen disposal hook.\n    const stop = router.stop.bind(router);\n    router.stop = () => { ++generation; if (current)\n        disposeScreen(current); current = undefined; stop(); };\n    const navigate = router.navigate.bind(router);\n    router.navigate = path => { ++generation; if (current)\n        disposeScreen(current); current = undefined; navigate(path); };\n    const screens = [\n        ['rotate', 'Rotate keys', renderRotate], ['autopilot', 'Autopilot', renderAutopilot],\n        ['activity', 'Activity', renderActivity], ['notifications', 'Notifications', renderNotifications],\n        ['approvals', 'Approvals', renderApprovals], ['settings', 'Settings', renderSettings], ['card', 'Readiness card', renderCard],\n    ];\n    for (const [path, title, render] of screens)\n        router.register(path, { title, async render() {\n                const renderGeneration = ++generation;\n                const hash = location.hash;\n                if (current)\n                    disposeScreen(current);\n                current = undefined;\n                const content = await render(session);\n                if (renderGeneration !== generation || hash !== location.hash)\n                    disposeScreen(content);\n                else\n                    current = content;\n                return content;\n            } });\n}\n","sha256":"dJ1/B1mQONlhS1I0ezPyhVoPzMzNu748UzDI/JLGOh4="},
  "/app/screens/card.js": {"type":"text/javascript; charset=utf-8","body":"import { post } from '../api.js';\nimport { actions, download, el, field, input, lifetime, message, paragraph, status, taskButton } from './components-b.js';\nasync function pngFromImage(image, signal) {\n    if (signal.aborted)\n        throw new Error();\n    await image.decode();\n    if (signal.aborted)\n        throw new Error();\n    const canvas = document.createElement('canvas');\n    canvas.width = 1200;\n    canvas.height = 630;\n    const context = canvas.getContext('2d');\n    if (!context)\n        throw new Error();\n    context.drawImage(image, 0, 0, canvas.width, canvas.height);\n    return new Promise((resolve, reject) => {\n        canvas.toBlob(blob => { if (blob && !signal.aborted)\n            resolve(blob);\n        else\n            reject(new Error()); }, 'image/png');\n    });\n}\n/** SVG is decoded as an image, never inserted into the page's document. */\nexport async function renderCard(_session) {\n    const root = el('div', undefined, 'screen-b');\n    const life = lifetime(root);\n    const feedback = status();\n    const platform = input('platform', 'checkbox');\n    const counts = input('counts', 'checkbox');\n    const preview = el('img', undefined, 'b-readiness-card');\n    preview.width = 1200;\n    preview.height = 630;\n    preview.alt = 'Readiness card preview';\n    const score = paragraph('Preparing the readiness card.');\n    let generation = 0;\n    let current;\n    let objectUrl;\n    let busy = false;\n    life.onDispose(() => { generation++; current = undefined; if (objectUrl)\n        URL.revokeObjectURL(objectUrl); objectUrl = undefined; preview.removeAttribute('src'); });\n    const update = async () => {\n        const request = ++generation;\n        busy = true;\n        copy.disabled = true;\n        save.disabled = true;\n        try {\n            const card = await post('card', { platform: platform.checked, counts: counts.checked });\n            if (life.signal.aborted || request !== generation)\n                return;\n            const blob = new Blob([card.svg], { type: 'image/svg+xml' });\n            const nextUrl = URL.createObjectURL(blob);\n            const previous = objectUrl;\n            objectUrl = nextUrl;\n            current = blob;\n            preview.src = nextUrl;\n            if (previous)\n                URL.revokeObjectURL(previous);\n            score.textContent = `Readiness ${card.score}/100.`;\n            feedback.replaceChildren();\n        }\n        catch {\n            if (!life.signal.aborted && request === generation) {\n                current = undefined;\n                if (objectUrl)\n                    URL.revokeObjectURL(objectUrl);\n                objectUrl = undefined;\n                preview.removeAttribute('src');\n                message(feedback, 'Card unavailable', 'The readiness card could not be prepared. Change an option to try again.', 'attention');\n            }\n        }\n        finally {\n            if (!life.signal.aborted && request === generation) {\n                busy = false;\n                copy.disabled = !current;\n                save.disabled = !current;\n            }\n        }\n    };\n    preview.addEventListener('error', () => { if (!life.signal.aborted && current)\n        message(feedback, 'Preview unavailable', 'This browser could not display the card. You can still choose Download SVG.', 'attention'); });\n    const save = taskButton('Download SVG', feedback, async () => { if (current && !busy && !life.signal.aborted)\n        download(current, 'keysentry-readiness.svg'); });\n    const copy = taskButton('Copy image', feedback, async () => {\n        if (!current || busy || life.signal.aborted)\n            return;\n        if (!navigator.clipboard?.write || typeof ClipboardItem === 'undefined' || typeof preview.decode !== 'function') {\n            message(feedback, 'Copy image unavailable', 'This browser cannot copy an image here. Choose Download SVG to save the card.');\n            return;\n        }\n        let png;\n        try {\n            const version = generation;\n            const snapshot = new Image();\n            snapshot.src = preview.src;\n            png = pngFromImage(snapshot, life.signal);\n            const item = new ClipboardItem({ 'image/png': png });\n            await navigator.clipboard.write([item]);\n            if (!life.signal.aborted && version === generation)\n                message(feedback, 'Image copied', 'The readiness card was copied as a PNG image.', 'ok');\n        }\n        catch {\n            if (png)\n                await png.catch(() => { });\n            if (!life.signal.aborted)\n                message(feedback, 'Copy image unavailable', 'The image could not be copied. Choose Download SVG to save the card.');\n        }\n    });\n    platform.addEventListener('change', () => { void update(); });\n    counts.addEventListener('change', () => { void update(); });\n    root.append(paragraph('The card shares your readiness score. Platform names and rotation counts are included only when you choose them below.'), field('Include platform names', platform), field('Include rotation counts', counts), score, preview, actions(save, copy), feedback);\n    await update();\n    return root;\n}\n","sha256":"uEsIkH5oDkH2JDuPfzTx347URYA1GxxNkMVHK0+aGEI="},
  "/app/screens/components-a.js": {"type":"text/javascript; charset=utf-8","body":"import { table } from '../components.js';\nexport function element(tag, text, className) {\n    const node = document.createElement(tag);\n    if (text !== undefined)\n        node.textContent = text;\n    if (className)\n        node.className = className;\n    return node;\n}\nexport function section(title) {\n    const block = element('section', undefined, 'screen-a-section');\n    block.append(element('h2', title));\n    return block;\n}\nexport function routeLink(text, route) {\n    const anchor = element('a', text);\n    anchor.href = `#/${route}`;\n    return anchor;\n}\nexport function count(value, singular, plural = `${singular}s`) {\n    return `${value} ${value === 1 ? singular : plural}`;\n}\nconst hosts = {\n    railway: 'Railway', vercel: 'Vercel', render: 'Render', fly: 'Fly', 'github-actions': 'GitHub Actions', dotenv: 'Local files',\n};\nexport function hostName(host) { return hosts[host] ?? host; }\nconst providers = {\n    openai: 'OpenAI', anthropic: 'Anthropic', openrouter: 'OpenRouter', stripe: 'Stripe', resend: 'Resend',\n    cloudflare: 'Cloudflare', github: 'GitHub', aws: 'AWS', supabase: 'Supabase', database: 'Database', slack: 'Slack',\n    sendgrid: 'SendGrid', twilio: 'Twilio', google: 'Google', 'private-key': 'Private key', 'crypto-wallet': 'Wallet',\n    'app-secret': 'App secret', 'encryption-key': 'Encryption key', unknown: 'Unknown provider',\n};\nexport function providerName(provider) { return providers[provider] ?? provider; }\nexport function scrollTable(columns, rows, caption) {\n    const wrapper = element('div', undefined, 'table-scroll');\n    wrapper.tabIndex = 0;\n    wrapper.setAttribute('role', 'region');\n    wrapper.setAttribute('aria-label', caption);\n    wrapper.append(table(columns, rows, caption));\n    return wrapper;\n}\n/** Documentation is an outbound link only; never turn an arbitrary response into executable navigation. */\nexport function documentationLink(url) {\n    try {\n        const target = new URL(url);\n        if (target.protocol !== 'https:' || target.username || target.password)\n            return null;\n        const anchor = element('a', 'How to create it');\n        anchor.href = target.href;\n        anchor.target = '_blank';\n        anchor.rel = 'noopener noreferrer';\n        return anchor;\n    }\n    catch {\n        return null;\n    }\n}\n","sha256":"pf09Ev00sGLt7joeE+lRmmnlWzyN/Ya37BbTr02VCv0="},
  "/app/screens/components-b.js": {"type":"text/javascript; charset=utf-8","body":"import { button, notice } from '../components.js';\nexport function el(tag, text, className) {\n    const node = document.createElement(tag);\n    if (text !== undefined)\n        node.textContent = text;\n    if (className)\n        node.className = className;\n    return node;\n}\nexport const paragraph = (text) => el('p', text);\nexport function field(label, control) {\n    const wrapper = el('label', undefined, 'b-field');\n    wrapper.append(el('span', label), control);\n    return wrapper;\n}\nexport function input(name, type, value) {\n    const control = el('input');\n    control.name = name;\n    control.type = type;\n    if (value !== undefined)\n        control.value = value;\n    return control;\n}\nexport function actions(...nodes) {\n    const group = el('div', undefined, 'b-actions');\n    group.append(...nodes);\n    return group;\n}\nexport function status() { const region = el('div', undefined, 'b-feedback'); region.setAttribute('role', 'status'); region.setAttribute('aria-live', 'polite'); return region; }\nexport function message(target, title, text, kind = 'info') {\n    target.replaceChildren(notice(kind, title, text));\n}\nexport function taskButton(label, feedback, run, disabled = false) {\n    const disabledNow = () => typeof disabled === 'function' ? disabled() : disabled;\n    const control = button(label, () => {\n        if (control.disabled || disabledNow())\n            return;\n        control.disabled = true;\n        control.setAttribute('aria-busy', 'true');\n        void run().catch(() => { message(feedback, 'Request not completed', 'The request could not be completed. Try again.', 'attention'); })\n            .finally(() => { control.disabled = disabledNow(); control.removeAttribute('aria-busy'); });\n    });\n    control.disabled = disabledNow();\n    return control;\n}\nexport function scrollTable(content) { const wrapper = el('div', undefined, 'table-scroll'); wrapper.append(content); return wrapper; }\nexport function section(title, ...nodes) { const block = el('section', undefined, 'b-section'); block.append(el('h2', title), ...nodes); return block; }\nexport function list(items) { const block = el('ul'); for (const item of items)\n    block.append(el('li', item)); return block; }\nexport function dateTime(value) {\n    if (!value)\n        return 'Not yet';\n    const date = new Date(value);\n    return Number.isFinite(date.getTime()) ? date.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }) : 'Date unavailable';\n}\nexport function numberInput(name, value, min, max) {\n    const control = input(name, 'number', String(value));\n    control.min = String(min);\n    control.step = '1';\n    control.required = true;\n    if (max !== undefined)\n        control.max = String(max);\n    return control;\n}\nexport function validNumber(control, min, max = Number.MAX_SAFE_INTEGER, integer = true) {\n    const number = control.valueAsNumber;\n    return Number.isFinite(number) && number >= min && number <= max && (!integer || Number.isSafeInteger(number)) ? number : null;\n}\nconst lifetimes = new WeakMap();\n/** The shell has no screen disposal hook; registration and DOM removal share this bounded lifetime. */\nexport function lifetime(root) {\n    const existing = lifetimes.get(root);\n    if (existing)\n        return existing;\n    const controller = new AbortController();\n    const cleanup = new Set();\n    const mounts = new Set();\n    let mounted = false;\n    const initialHash = location.hash;\n    const dispose = () => {\n        if (controller.signal.aborted)\n            return;\n        controller.abort();\n        observer.disconnect();\n        window.removeEventListener('pagehide', dispose);\n        window.removeEventListener('hashchange', changed);\n        for (const callback of cleanup)\n            callback();\n        cleanup.clear();\n        mounts.clear();\n    };\n    const changed = () => { if (location.hash !== initialHash)\n        dispose(); };\n    const inspect = () => {\n        if (controller.signal.aborted)\n            return;\n        if (root.isConnected && !mounted) {\n            mounted = true;\n            for (const callback of mounts)\n                callback();\n            mounts.clear();\n        }\n        else if (mounted && !root.isConnected)\n            dispose();\n    };\n    const observer = new MutationObserver(inspect);\n    observer.observe(document.documentElement, { childList: true, subtree: true });\n    window.addEventListener('pagehide', dispose);\n    window.addEventListener('hashchange', changed);\n    const scope = {\n        signal: controller.signal, dispose,\n        onDispose(callback) { if (controller.signal.aborted)\n            callback();\n        else\n            cleanup.add(callback); },\n        onMount(callback) { if (controller.signal.aborted)\n            return; if (root.isConnected) {\n            mounted = true;\n            callback();\n        }\n        else\n            mounts.add(callback); },\n    };\n    lifetimes.set(root, scope);\n    return scope;\n}\nexport function disposeScreen(root) { lifetimes.get(root)?.dispose(); }\n/** Download names are fixed by the screen, never interpolated from API data. */\nexport function download(blob, filename) {\n    const url = URL.createObjectURL(blob);\n    const link = el('a');\n    link.href = url;\n    link.download = filename;\n    document.body.append(link);\n    try {\n        link.click();\n    }\n    finally {\n        link.remove();\n        window.setTimeout(() => URL.revokeObjectURL(url), 0);\n    }\n}\n","sha256":"TMhLLdPj1lpbFmQmWLrMFqVOpNyIPvkvUPbGZti4oz0="},
  "/app/screens/connect.js": {"type":"text/javascript; charset=utf-8","body":"import { get, postWithPasskey } from '../api.js';\nimport { button, emptyState } from '../components.js';\nimport { documentationLink, element, section } from './components-a.js';\nfunction tokenForm(platform, readOnly) {\n    const form = element('form', undefined, 'screen-a-token-form');\n    form.autocomplete = 'off';\n    form.setAttribute('aria-label', `Store ${platform.name} token`);\n    const name = element('select');\n    name.name = 'name';\n    name.required = true;\n    for (const token of [...platform.tokens].sort((a, b) => Number(b.recommended) - Number(a.recommended))) {\n        const option = element('option', token.name);\n        option.value = token.name;\n        name.append(option);\n    }\n    const role = element('select');\n    role.name = 'role';\n    role.required = true;\n    for (const value of ['read', 'write']) {\n        if (!platform.roles.includes(value))\n            continue;\n        const option = element('option', value === 'read' ? 'Read: scan and monitor' : 'Write: approved changes');\n        option.value = value;\n        role.append(option);\n    }\n    const value = element('input');\n    value.type = 'password';\n    value.name = 'value';\n    value.autocomplete = 'off';\n    value.required = true;\n    value.spellcheck = false;\n    for (const [label, field] of [['Token name', name], ['Token role', role], ['Token value', value]]) {\n        const wrapper = element('label', label);\n        wrapper.append(field);\n        form.append(wrapper);\n        field.disabled = readOnly;\n    }\n    const explanation = element('p', 'keysentry will store this token in your vault after passkey verification. The value is cleared from this form when you choose Store token.');\n    const status = element('p');\n    status.setAttribute('role', 'status');\n    const store = button('Store token');\n    store.type = 'submit';\n    store.disabled = readOnly || name.options.length === 0 || role.options.length === 0;\n    let pending = false;\n    form.addEventListener('submit', event => {\n        event.preventDefault();\n        if (readOnly || pending) {\n            value.value = '';\n            return;\n        }\n        if (!name.value || !value.value || !['read', 'write'].includes(role.value))\n            return;\n        pending = true;\n        store.disabled = true;\n        status.textContent = 'Waiting for passkey verification.';\n        const body = { name: name.value, role: role.value, value: value.value };\n        value.value = '';\n        void (async () => {\n            try {\n                // The helper snapshots canonical JSON before its first await. Release our plaintext immediately.\n                let request;\n                try {\n                    request = postWithPasskey('vault/store', body);\n                }\n                finally {\n                    body.value = '';\n                }\n                await request;\n                status.textContent = 'Stored token.';\n            }\n            catch {\n                status.textContent = 'Token was not stored. Enter it again and try Store token.';\n            }\n            finally {\n                body.value = '';\n                value.value = '';\n                pending = false;\n                store.disabled = readOnly;\n            }\n        })();\n    });\n    form.append(explanation, store, status);\n    return form;\n}\nexport async function renderConnect(session) {\n    const { platforms } = await get('platforms');\n    const page = element('div', undefined, 'screen-a connect-screen');\n    page.append(element('p', 'Choose the narrowest token for the platform you want to connect. Review what it can do before storing it.'));\n    if (!platforms.length) {\n        page.append(emptyState('No platforms are available to connect in this project. Run keysentry in your project folder to review its configuration.'));\n        return page;\n    }\n    for (const platform of platforms) {\n        const block = section(platform.name);\n        block.dataset.platform = platform.host;\n        block.append(element('p', platform.connected ? 'Connected' : 'Not connected', 'screen-a-state'));\n        block.append(element('p', platform.source === 'vault' ? 'Stored in the vault.' : platform.source === 'env' ? 'Provided by an environment variable.' : 'No token stored.', 'screen-a-muted'));\n        for (const token of [...platform.tokens].sort((a, b) => Number(b.recommended) - Number(a.recommended))) {\n            const details = element('section', undefined, 'screen-a-token');\n            const title = element('h3');\n            title.append(element('code', token.name), document.createTextNode(token.recommended ? ' (recommended)' : ''));\n            details.append(title, element('p', `Scope: ${token.scope}.`));\n            const capability = token.canReadValues\n                ? `read key values${token.canWrite ? ' and write keys' : ', but cannot write keys'}`\n                : `${token.canWrite ? 'write keys' : 'list key names'}, but cannot read back key values`;\n            details.append(element('p', `This token can ${capability}. keysentry will only ${platform.keysentryUses.scan} when scanning; it will only ${platform.keysentryUses.rotate} after you approve a change.`));\n            const how = documentationLink(token.howToCreate);\n            if (how)\n                details.append(how);\n            else\n                details.append(element('p', 'Creation instructions are unavailable. Review the platform documentation before creating a token.'));\n            details.append(element('p', `Source: ${token.source}`, 'screen-a-muted'));\n            block.append(details);\n        }\n        block.append(tokenForm(platform, session.readOnly));\n        page.append(block);\n    }\n    return page;\n}\n","sha256":"QG/2PsXbKk9lnLZJaUL8Zay8J1pXBuSj/Y2xi9k77/4="},
  "/app/screens/home.js": {"type":"text/javascript; charset=utf-8","body":"import { get } from '../api.js';\nimport { emptyState } from '../components.js';\nimport { count, element, hostName, routeLink, section } from './components-a.js';\nexport async function renderHome() {\n    const overview = await get('overview');\n    const page = element('div', undefined, 'screen-a overview-screen');\n    if (!overview.firstRun && overview.keys === 0)\n        page.append(emptyState('Run keysentry in your project folder to see your keys.'));\n    else {\n        page.append(element('p', `This project has ${count(overview.keys, 'key')}. ${count(overview.inGitHistory, 'key')} ${overview.inGitHistory === 1 ? 'appears' : 'appear'} in git history.`));\n        if (overview.needsRotation)\n            page.append(element('p', `${count(overview.needsRotation, 'key')} ${overview.needsRotation === 1 ? 'needs' : 'need'} rotation. Review the places each key is used before choosing a change.`));\n    }\n    const scan = overview.firstRun;\n    if (scan) {\n        page.append(element('p', `Scanned ${count(scan.scannedFiles, 'file')} and ${count(scan.scannedCommits, 'commit')}. ${scan.historyComplete ? 'The git history scan is complete.' : 'The git history scan is incomplete; there may be more keys in older commits.'}`, 'screen-a-muted'));\n        if (scan.deployTargets.length) {\n            const targets = [...new Set(scan.deployTargets.map(target => hostName(target.host)))];\n            const deployment = section('Likely deployment platforms');\n            deployment.append(element('p', `Project files suggest this project deploys to ${targets.join(', ')}.`));\n            const evidence = element('ul');\n            for (const target of scan.deployTargets) {\n                const item = element('li', `${hostName(target.host)}: `);\n                item.append(element('code', target.evidence));\n                evidence.append(item);\n            }\n            deployment.append(evidence);\n            page.append(deployment);\n        }\n        else\n            page.append(element('p', 'No deployment platforms were identified from project files.'));\n    }\n    page.append(element('p', overview.connectedPlatforms.length ? `Connected platforms: ${overview.connectedPlatforms.map(hostName).join(', ')}.` : 'No platforms connected yet. Connect Railway, Vercel, Render or Fly to see where your keys are deployed.'));\n    page.append(element('p', `Autopilot is ${overview.autopilot === 'alert-only' ? 'in alert-only mode' : overview.autopilot}.`));\n    const nextSteps = overview.nextSteps.length ? overview.nextSteps : scan?.nextSteps ?? [];\n    if (nextSteps.length) {\n        const next = section('Next steps');\n        const list = element('ol');\n        for (const text of nextSteps)\n            list.append(element('li', text));\n        next.append(list);\n        page.append(next);\n    }\n    const links = element('nav', undefined, 'screen-a-links');\n    links.setAttribute('aria-label', 'Project next steps');\n    for (const [title, route] of [['See your keys', 'keys'], ['Connect a platform', 'connect'], ['Review access', 'access'], ['Review network', 'network'], ['Practise a rotation', 'rotate'], ['Review autopilot', 'autopilot']])\n        links.append(routeLink(title, route));\n    page.append(links);\n    return page;\n}\n","sha256":"AEd+NHuzawtIaPeZQLdrwKA3y9bAovmODkVCUCme1L0="},
  "/app/screens/keys.js": {"type":"text/javascript; charset=utf-8","body":"import { get } from '../api.js';\nimport { button, disposeComponents, emptyState, keyTag, maskedValue } from '../components.js';\nimport { element, hostName, providerName, routeLink, scrollTable } from './components-a.js';\nlet panelNumber = 0;\nexport async function renderKeys(session) {\n    const { keys } = await get('keys');\n    const page = element('div', undefined, 'screen-a keys-screen');\n    page.append(element('p', 'Choose a key tag to see every place it lives. Opening a tag does not reveal its value or make a change.'));\n    if (!keys.length) {\n        page.append(emptyState('Run keysentry in your project folder to see your keys.'));\n        page.append(routeLink('Connect a platform', 'connect'));\n        return page;\n    }\n    const filters = element('div', undefined, 'screen-a-filters');\n    const cabinet = element('div', undefined, 'screen-a-cabinet');\n    const results = element('p', undefined, 'screen-a-muted');\n    results.setAttribute('role', 'status');\n    const grid = element('div', undefined, 'key-grid');\n    grid.setAttribute('role', 'group');\n    grid.setAttribute('aria-label', 'Key cabinet');\n    const detail = element('div', undefined, 'screen-a-detail');\n    const selected = { state: new Set(), host: new Set(), provider: new Set() };\n    let selectedTag;\n    let tags = [];\n    const toggles = [];\n    const close = (restoreFocus = true) => {\n        disposeComponents(detail);\n        detail.replaceChildren();\n        selectedTag?.setAttribute('aria-expanded', 'false');\n        selectedTag?.removeAttribute('aria-controls');\n        if (restoreFocus && selectedTag?.isConnected)\n            selectedTag.focus();\n        selectedTag = undefined;\n        cabinet.classList.remove('has-detail');\n    };\n    const focusTag = (index) => {\n        for (let i = 0; i < tags.length; i++)\n            tags[i].tabIndex = i === index ? 0 : -1;\n        tags[index]?.focus();\n    };\n    const open = (key, tag) => {\n        close(false);\n        selectedTag = tag;\n        focusTag(tags.indexOf(tag));\n        tag.setAttribute('aria-expanded', 'true');\n        const panel = element('section', undefined, 'screen-a-key-panel');\n        panel.id = `key-panel-${++panelNumber}`;\n        panel.setAttribute('role', 'dialog');\n        panel.setAttribute('aria-modal', 'false');\n        const heading = element('h2', `${providerName(key.provider)} key`);\n        heading.id = `${panel.id}-heading`;\n        heading.tabIndex = -1;\n        panel.setAttribute('aria-labelledby', heading.id);\n        tag.setAttribute('aria-controls', panel.id);\n        panel.append(heading, element('code', key.hint ?? 'Hint unavailable'), element('p', key.stateText, `screen-a-state state-${key.state}`));\n        panel.append(element('p', key.inGitHistory ? 'In git history. Rotate this key even if it has been removed from current files.' : 'Not found in the scanned git history.'));\n        panel.append(element('p', key.rotateBy ? `Rotate by ${key.rotateBy}.` : 'No rotate-by date is available.'));\n        if (key.places.length)\n            panel.append(scrollTable(['Place', 'Platform', 'Variable', 'Access'], key.places.map(place => [place.label, hostName(place.host), element('code', place.variable), place.writeOnly ? 'Write-only' : 'Readable']), 'Places this key lives'));\n        else\n            panel.append(element('p', 'No current places are listed for this key.'));\n        panel.append(element('p', 'Review a rotation plan before approving changes. Revealing a readable value requires passkey verification.'));\n        const actions = element('div', undefined, 'screen-a-links');\n        actions.append(routeLink('Rotate this key', `rotate?key=${encodeURIComponent(key.id)}`), button('Close', () => close(), 'secondary'));\n        panel.append(actions);\n        const readable = key.places.some(place => !place.writeOnly);\n        const value = maskedValue({ route: 'reveal', body: { clusterId: key.id } });\n        if (session.readOnly || !readable) {\n            for (const control of value.querySelectorAll('button'))\n                control.disabled = true;\n        }\n        panel.append(value);\n        if (!readable)\n            panel.append(element('p', 'Reveal is unavailable because no readable place is listed for this key.'));\n        detail.append(panel);\n        cabinet.classList.add('has-detail');\n        heading.focus();\n    };\n    const renderTags = () => {\n        close(false);\n        const visible = keys.filter(key => (!selected.state.size || selected.state.has(key.stateText)) &&\n            (!selected.provider.size || selected.provider.has(key.provider)) &&\n            (!selected.host.size || key.places.some(place => selected.host.has(place.host))));\n        grid.replaceChildren();\n        tags = [];\n        results.textContent = `Showing ${visible.length} of ${keys.length} keys.`;\n        if (!visible.length)\n            grid.append(emptyState('No keys match these filters.'));\n        for (const key of visible) {\n            const tag = keyTag({ provider: providerName(key.provider), hint: key.hint, state: key.stateText, copies: key.places.length, ageDays: key.ageDays }, () => open(key, tag));\n            tag.dataset.state = key.state;\n            tag.setAttribute('aria-haspopup', 'dialog');\n            tag.setAttribute('aria-expanded', 'false');\n            tag.tabIndex = tags.length ? -1 : 0;\n            tag.addEventListener('keydown', event => {\n                if (event.key === 'Enter' || event.key === ' ') {\n                    event.preventDefault();\n                    open(key, tag);\n                    return;\n                }\n                const direction = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[event.key];\n                if (direction !== undefined) {\n                    event.preventDefault();\n                    focusTag((tags.indexOf(tag) + direction + tags.length) % tags.length);\n                }\n                if (event.key === 'Home' || event.key === 'End') {\n                    event.preventDefault();\n                    focusTag(event.key === 'Home' ? 0 : tags.length - 1);\n                }\n            });\n            tags.push(tag);\n            grid.append(tag);\n        }\n    };\n    const filterGroup = (title, selection, values, label) => {\n        const group = element('fieldset', undefined, 'screen-a-filter');\n        group.append(element('legend', title));\n        for (const value of [...new Set(values)]) {\n            const control = button(label(value), () => {\n                if (selection.has(value))\n                    selection.delete(value);\n                else\n                    selection.add(value);\n                control.setAttribute('aria-pressed', String(selection.has(value)));\n                renderTags();\n            }, 'secondary');\n            control.setAttribute('aria-pressed', 'false');\n            toggles.push({ control, selection, value });\n            group.append(control);\n        }\n        filters.append(group);\n    };\n    filterGroup('State', selected.state, keys.map(key => key.stateText), value => value);\n    filterGroup('Platform', selected.host, keys.flatMap(key => key.places.map(place => place.host)), hostName);\n    filterGroup('Provider', selected.provider, keys.map(key => key.provider), providerName);\n    filters.append(button('Clear filters', () => {\n        for (const filter of toggles) {\n            filter.selection.clear();\n            filter.control.setAttribute('aria-pressed', 'false');\n        }\n        renderTags();\n    }, 'secondary'));\n    page.addEventListener('keydown', event => { if (event.key === 'Escape' && selectedTag) {\n        event.preventDefault();\n        close();\n    } });\n    cabinet.append(grid, detail);\n    page.append(filters, results, cabinet);\n    renderTags();\n    return page;\n}\n","sha256":"Rjzz+AQvDrMHlliwfLPHKxAOdrPA4uWKn8iP+l6eR9w="},
  "/app/screens/network.js": {"type":"text/javascript; charset=utf-8","body":"import { get } from '../api.js';\nimport { emptyState, table } from '../components.js';\nfunction scrollTable(content) {\n    const wrapper = document.createElement('div');\n    wrapper.className = 'table-scroll';\n    wrapper.tabIndex = 0;\n    wrapper.setAttribute('role', 'region');\n    wrapper.setAttribute('aria-label', content.caption?.textContent ?? 'Network details');\n    wrapper.append(content);\n    return wrapper;\n}\n/** Hosts and aggregate request metadata only; paths and request bodies are never rendered. */\nexport async function renderNetwork() {\n    const { allowed, receipt } = await get('network');\n    const page = document.createElement('div');\n    page.className = 'screen-a-network';\n    const introduction = document.createElement('p');\n    introduction.textContent = 'These are the hosts keysentry is allowed to contact and the requests recorded in your network receipt.';\n    page.append(introduction);\n    if (allowed.length === 0)\n        page.append(emptyState('No hosts are allowed in this configuration. Review keysentry.yaml to configure network access.'));\n    const groups = new Map();\n    for (const host of allowed) {\n        const group = groups.get(host.purpose) ?? [];\n        group.push(host);\n        groups.set(host.purpose, group);\n    }\n    for (const [purpose, hosts] of groups) {\n        const section = document.createElement('section');\n        section.className = 'screen-a-section';\n        const heading = document.createElement('h2');\n        heading.textContent = purpose;\n        section.append(heading, scrollTable(table(['Host', 'Source'], hosts.map(host => [host.host, host.source]), `Allowed hosts: ${purpose}`)));\n        page.append(section);\n    }\n    const history = document.createElement('section');\n    history.className = 'screen-a-section';\n    const historyHeading = document.createElement('h2');\n    historyHeading.textContent = 'Receipt';\n    history.append(historyHeading);\n    if (receipt.length === 0)\n        history.append(emptyState('No requests have been recorded yet. Requests will appear here when keysentry contacts a platform.'));\n    else\n        history.append(scrollTable(table(['Host', 'Purpose', 'Requests', 'Blocked', 'Last contacted'], receipt.map(row => [row.host, row.purpose, String(row.count), String(row.blocked), row.lastAt]), 'Network receipt')));\n    page.append(history);\n    return page;\n}\n","sha256":"aq1BeGhut5Gb1Fj3194J245kYKhWvuUwzHb4e1KFy08="},
  "/app/screens/notifications.js": {"type":"text/javascript; charset=utf-8","body":"import { get, post, postWithPasskey } from '../api.js';\nimport { confirmAction, emptyState, table } from '../components.js';\nimport { actions, el, field, input, lifetime, message, paragraph, scrollTable, status, taskButton } from './components-b.js';\nconst kinds = {\n    telegram: { label: 'Telegram', fields: [{ name: 'botToken', label: 'Bot token', secret: true }, { name: 'chatId', label: 'Chat ID' }] },\n    discord: { label: 'Discord', fields: [{ name: 'webhookUrl', label: 'Webhook URL', secret: true }] },\n    slack: { label: 'Slack', fields: [{ name: 'webhookUrl', label: 'Webhook URL', secret: true }] },\n    ntfy: { label: 'ntfy', fields: [{ name: 'server', label: 'Server', value: 'https://ntfy.sh' }, { name: 'topic', label: 'Topic' }, { name: 'token', label: 'Access token (optional)', secret: true, optional: true }] },\n    webhook: { label: 'Webhook', fields: [{ name: 'url', label: 'Webhook URL', secret: true }] },\n    resend: { label: 'Resend', fields: [{ name: 'apiKey', label: 'API key', secret: true }, { name: 'from', label: 'From address' }, { name: 'to', label: 'To address' }] },\n    smtp: { label: 'SMTP', fields: [{ name: 'host', label: 'Mail server' }, { name: 'port', label: 'Port (465 or 587)', value: '465' }, { name: 'username', label: 'Username' }, { name: 'password', label: 'Password', secret: true }, { name: 'from', label: 'From address' }, { name: 'to', label: 'To address' }] },\n    console: { label: 'Console', fields: [] },\n};\n/** Channel responses contain metadata only; credentials exist only in the add request. */\nexport async function renderNotifications(session) {\n    const root = el('div', undefined, 'screen-b');\n    const life = lifetime(root);\n    let data = await get('notifications');\n    if (life.signal.aborted)\n        return root;\n    const feedback = status();\n    const channelList = el('section');\n    const refresh = async () => {\n        const next = await get('notifications');\n        if (!life.signal.aborted) {\n            data = next;\n            drawChannels();\n        }\n    };\n    const drawChannels = () => {\n        channelList.replaceChildren(el('h2', 'Channels'));\n        if (!data.channels.length) {\n            channelList.append(emptyState('Add a channel to receive signed messages from keysentry.'));\n            return;\n        }\n        channelList.append(scrollTable(table(['Channel', 'Kind', 'Last successful delivery', 'Action'], data.channels.map(channel => {\n            const remove = taskButton('Remove', feedback, async () => {\n                if (!await confirmAction({ title: 'Remove channel', changes: [`keysentry will stop sending notifications to ${channel.label}.`], button: 'Remove', signal: life.signal }))\n                    return;\n                if (life.signal.aborted)\n                    return;\n                const result = await postWithPasskey('notifications/remove', { id: channel.id });\n                if (life.signal.aborted)\n                    return;\n                if (result.removed) {\n                    data.channels = data.channels.filter(item => item.id !== channel.id);\n                    drawChannels();\n                    message(feedback, 'Channel removed', 'keysentry will no longer send notifications to this channel.', 'ok');\n                }\n                else\n                    message(feedback, 'Channel unchanged', 'The channel was not removed. Refresh the page and try again.', 'attention');\n            }, session.readOnly);\n            return [channel.label, kinds[channel.kind]?.label ?? channel.kind, channel.lastSuccessAt ? new Date(channel.lastSuccessAt).toLocaleString() : 'No successful delivery yet', remove];\n        }), 'Notification channels')));\n    };\n    drawChannels();\n    const testAll = taskButton('Test all channels', feedback, async () => {\n        if (life.signal.aborted)\n            return;\n        const result = await postWithPasskey('notifications/test', {});\n        if (life.signal.aborted)\n            return;\n        await refresh();\n        if (life.signal.aborted)\n            return;\n        message(feedback, 'Channels tested', `${result.delivered.length} delivered; ${result.failed.length} could not be delivered.${result.failed.length ? ' Check the channel settings and try again.' : ''}`, result.failed.length ? 'attention' : 'ok');\n    }, session.readOnly);\n    root.append(paragraph('Messages are signed by your device. Adding or removing a channel changes where future notifications are sent.'), channelList, paragraph('Test all channels sends one test message to every configured channel.'), actions(testAll));\n    const form = el('form', undefined, 'b-form');\n    form.addEventListener('submit', event => event.preventDefault());\n    const kind = el('select');\n    kind.name = 'kind';\n    kind.disabled = session.readOnly;\n    for (const [id, definition] of Object.entries(kinds)) {\n        const option = el('option', definition.label);\n        option.value = id;\n        kind.append(option);\n    }\n    const label = input('label', 'text');\n    label.required = true;\n    label.maxLength = 120;\n    label.disabled = session.readOnly;\n    const config = el('div', undefined, 'b-form');\n    let fields = [];\n    const clearSecrets = () => { for (const item of fields)\n        if (item.definition.secret)\n            item.control.value = ''; };\n    const drawFields = () => {\n        clearSecrets();\n        fields = [];\n        config.replaceChildren();\n        for (const definition of kinds[kind.value].fields) {\n            const control = input(definition.name, definition.secret ? 'password' : 'text', definition.value ?? '');\n            control.required = !definition.optional;\n            control.autocomplete = 'off';\n            control.disabled = session.readOnly;\n            if (definition.name === 'port') {\n                control.inputMode = 'numeric';\n                control.pattern = '465|587';\n            }\n            fields.push({ definition, control });\n            config.append(field(definition.label, control));\n        }\n    };\n    kind.addEventListener('change', drawFields);\n    drawFields();\n    life.onDispose(clearSecrets);\n    const add = taskButton('Add channel', feedback, async () => {\n        if (!form.reportValidity() || life.signal.aborted)\n            return;\n        const settings = {};\n        for (const item of fields)\n            if (item.control.value || !item.definition.optional)\n                settings[item.definition.name] = item.control.value;\n        const body = { kind: kind.value, label: label.value.trim(), settings };\n        clearSecrets();\n        if (!body.label) {\n            message(feedback, 'Choose a channel label', 'Enter a short name you will recognize.', 'attention');\n            return;\n        }\n        // The shared helper snapshots canonical request bytes before its first await.\n        // Release the screen's temporary credential copies while the passkey prompt is open.\n        const request = postWithPasskey('notifications/add', body);\n        for (const item of fields)\n            if (item.definition.secret)\n                settings[item.definition.name] = '';\n        await request;\n        if (life.signal.aborted)\n            return;\n        await refresh();\n        if (!life.signal.aborted)\n            message(feedback, 'Channel added', 'Future notifications will include this channel. Test it to check delivery.', 'ok');\n    }, session.readOnly);\n    add.type = 'submit';\n    form.append(el('h2', 'Add a channel'), paragraph('keysentry will store these channel settings for future notifications. Credentials are sent only when you choose Add channel and verify with your passkey.'), field('Kind', kind), field('Channel label', label), config, actions(add));\n    const verify = el('form', undefined, 'b-form');\n    verify.addEventListener('submit', event => event.preventDefault());\n    const code = input('code', 'text');\n    code.required = true;\n    code.autocomplete = 'off';\n    const check = taskButton('Check a message', feedback, async () => {\n        if (!verify.reportValidity() || life.signal.aborted)\n            return;\n        const result = await post('notifications/verify', { code: code.value.trim() });\n        if (!life.signal.aborted)\n            message(feedback, result.valid ? 'Message verified' : 'Message not verified', result.message, result.valid ? 'ok' : 'attention');\n    });\n    check.type = 'submit';\n    verify.append(el('h2', 'Check a message'), paragraph('Enter the verification code from a notification to check its signature.'), field('Verification code', code), actions(check));\n    root.append(form, verify, feedback);\n    return root;\n}\n","sha256":"hyc/jyIAOrd82LW8vuAN1lisLnfaU/VlhT3m69+eKYU="},
  "/app/screens/rotate.js": {"type":"text/javascript; charset=utf-8","body":"import { get, post, postWithPasskey } from '../api.js';\nimport { button, confirmAction, emptyState, table } from '../components.js';\nimport { actions, dateTime, el, field, input, lifetime, list, message, paragraph, scrollTable, section, status, taskButton } from './components-b.js';\nexport async function renderRotate(session) {\n    const [{ keys }, rotations] = await Promise.all([get('keys'), get('rotations')]);\n    const root = el('div', undefined, 'screen-b');\n    const scope = lifetime(root);\n    const feedback = status();\n    const initialHash = location.hash;\n    const live = () => !scope.signal.aborted && location.hash === initialHash;\n    const selected = new Set();\n    const preselected = new URLSearchParams(location.hash.split('?')[1]).get('key');\n    const choices = el('fieldset');\n    choices.append(el('legend', 'Choose keys'));\n    for (const key of keys) {\n        const choice = input(key.id, 'checkbox');\n        choice.checked = key.id === preselected;\n        if (choice.checked)\n            selected.add(key.id);\n        choice.addEventListener('change', () => { if (choice.checked)\n            selected.add(key.id);\n        else\n            selected.delete(key.id); });\n        choices.append(field(`${key.provider} · ${key.hint ?? 'Hint unavailable'} · ${key.method}`, choice));\n    }\n    if (!keys.length)\n        choices.append(emptyState('No keys to rotate yet. Connect a platform and scan your keys.'));\n    const previewDetail = el('div');\n    const progress = el('div');\n    let active = rotations.active;\n    let progressSnapshot;\n    const busyPlans = new Set();\n    const graceControls = new Map();\n    const updateControls = () => { for (const [id, controls] of graceControls)\n        for (const control of controls)\n            control.disabled = session.readOnly || busyPlans.has(id); };\n    const runGrace = async (id, action) => {\n        if (busyPlans.has(id) || scope.signal.aborted)\n            return;\n        busyPlans.add(id);\n        updateControls();\n        try {\n            await action();\n        }\n        finally {\n            busyPlans.delete(id);\n            updateControls();\n        }\n    };\n    let pollTimer;\n    let clockTimer;\n    let mounted = false;\n    let refreshing = false;\n    let clocks = [];\n    const stopTimers = () => { if (pollTimer !== undefined)\n        window.clearTimeout(pollTimer); if (clockTimer !== undefined)\n        window.clearInterval(clockTimer); pollTimer = undefined; clockTimer = undefined; };\n    const startClock = () => { if (mounted && clocks.length && clockTimer === undefined)\n        clockTimer = window.setInterval(() => { for (const update of clocks)\n            update(); }, 1_000); };\n    scope.onDispose(stopTimers);\n    const clock = (rotation) => {\n        const block = el('div', undefined, 'b-countdown');\n        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');\n        svg.setAttribute('viewBox', '0 0 48 48');\n        svg.setAttribute('aria-hidden', 'true');\n        svg.classList.add('b-grace-ring');\n        const circle = document.createElementNS(svg.namespaceURI, 'circle');\n        circle.setAttribute('cx', '24');\n        circle.setAttribute('cy', '24');\n        circle.setAttribute('r', '20');\n        circle.setAttribute('pathLength', '100');\n        svg.append(circle);\n        const text = el('span');\n        const deadline = Date.parse(rotation.deadline);\n        const start = Date.parse(rotation.startedAt);\n        const total = Math.max(1, deadline - start);\n        let ringDrawn = false;\n        const update = () => {\n            const remaining = Math.max(0, deadline - Date.now());\n            const seconds = Math.ceil(remaining / 1000);\n            const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n            svg.classList.toggle('counting', remaining > 0 && Number.isFinite(remaining) && !reduced);\n            if (!ringDrawn || !reduced) {\n                circle.setAttribute('stroke-dasharray', '100');\n                circle.setAttribute('stroke-dashoffset', String(Number.isFinite(remaining) ? 100 * (1 - Math.min(1, remaining / total)) : 100));\n                ringDrawn = true;\n            }\n            text.textContent = !Number.isFinite(remaining) ? 'Grace deadline unavailable.' : seconds ? `${Math.floor(seconds / 60)}m ${String(seconds % 60).padStart(2, '0')}s remaining · ${dateTime(rotation.deadline)}` : `Grace deadline reached · ${dateTime(rotation.deadline)}. Check rotation status before revoking.`;\n        };\n        update();\n        clocks.push(update);\n        block.append(svg, text);\n        return block;\n    };\n    const showProgress = () => {\n        const snapshot = JSON.stringify(active);\n        if (snapshot === progressSnapshot)\n            return;\n        progressSnapshot = snapshot;\n        const focused = document.activeElement instanceof HTMLElement && progress.contains(document.activeElement) ? document.activeElement : undefined;\n        const focusedPlan = focused?.closest('[data-plan-id]')?.dataset.planId;\n        const focusedLabel = focused?.textContent;\n        clocks = [];\n        graceControls.clear();\n        progress.replaceChildren();\n        if (!active.length) {\n            progress.append(emptyState('No rotation is active. Preview a rotation to see exactly what will change.'));\n            return;\n        }\n        for (const rotation of active) {\n            const block = section(`Rotation ${rotation.planId}`, paragraph(`Status: ${rotation.status ?? 'In progress'}. Started ${dateTime(rotation.startedAt)}.`));\n            block.dataset.planId = rotation.planId;\n            block.append(scrollTable(table(['Key', 'Status', 'Notes'], rotation.steps.map(step => [step.hint ?? 'Hint unavailable', step.status, step.warnings.join(' ')]), 'Rotation progress')));\n            const timeline = el('a', 'View timeline');\n            timeline.href = `#activity?id=${encodeURIComponent(rotation.planId)}`;\n            block.append(timeline);\n            if (rotation.deadline)\n                block.append(clock(rotation));\n            if (rotation.status === 'grace-pending' && rotation.deadline) {\n                const finish = taskButton('Revoke old keys now', feedback, () => runGrace(rotation.planId, async () => {\n                    if (!await confirmAction({ title: 'Revoke old keys now', changes: ['keysentry will revoke the old keys for this rotation before the grace deadline. Undo may no longer be available.'], button: 'Revoke old keys now', signal: scope.signal }) || scope.signal.aborted)\n                        return;\n                    await postWithPasskey('rotation/finish', { planId: rotation.planId, early: true });\n                    if (!scope.signal.aborted) {\n                        message(feedback, 'Revocation requested', 'Check the rotation status below.');\n                        await refresh();\n                    }\n                }), session.readOnly);\n                const undo = taskButton('Undo', feedback, () => runGrace(rotation.planId, async () => {\n                    if (!await confirmAction({ title: 'Undo this rotation', changes: ['keysentry will restore the old keys where undo is still available.'], button: 'Undo', signal: scope.signal }) || scope.signal.aborted)\n                        return;\n                    const result = await postWithPasskey('rotation/undo', { planId: rotation.planId });\n                    if (!scope.signal.aborted) {\n                        message(feedback, 'Undo result', `${result.restored.length} keys restored.${result.unavailable.length ? ` ${result.unavailable.map(item => item.reason).join(' ')}` : ''}`, result.unavailable.length ? 'attention' : 'ok');\n                        await refresh();\n                    }\n                }), session.readOnly);\n                graceControls.set(rotation.planId, [finish, undo]);\n                const later = button('Later', () => message(feedback, 'Grace period continues', 'The grace deadline stays the same. Return here to review the rotation.'), 'secondary');\n                block.append(paragraph('The old keys remain available during grace. Revoking early may remove the option to undo.'), actions(finish, undo, later));\n            }\n            progress.append(block);\n        }\n        updateControls();\n        startClock();\n        if (focused) {\n            const plan = [...progress.querySelectorAll('[data-plan-id]')].find(node => node.dataset.planId === focusedPlan);\n            const replacement = [...(plan?.querySelectorAll('button, a') ?? [])].find(node => node.textContent === focusedLabel);\n            if (replacement && !(replacement instanceof HTMLButtonElement && replacement.disabled))\n                replacement.focus();\n            else {\n                progress.tabIndex = -1;\n                progress.focus();\n            }\n        }\n    };\n    const schedule = () => {\n        if (!mounted || !root.isConnected || !live() || !active.length || pollTimer !== undefined)\n            return;\n        pollTimer = window.setTimeout(() => { pollTimer = undefined; void refresh().catch(() => { if (!scope.signal.aborted)\n            message(feedback, 'Status unavailable', 'The rotation status could not be refreshed. keysentry will try again.', 'attention'); }).finally(schedule); }, 3_000);\n    };\n    const refresh = async () => {\n        if (!live() || refreshing)\n            return;\n        refreshing = true;\n        try {\n            const result = await get('rotations');\n            if (!scope.signal.aborted) {\n                active = result.active;\n                showProgress();\n                if (!active.length)\n                    stopTimers();\n                else\n                    schedule();\n            }\n        }\n        finally {\n            refreshing = false;\n        }\n    };\n    const preview = taskButton('Preview', feedback, async () => {\n        if (!selected.size) {\n            message(feedback, 'Choose keys', 'Choose at least one key to preview.', 'attention');\n            return;\n        }\n        const result = await post('rotate/preview', { clusterIds: [...selected] });\n        if (scope.signal.aborted)\n            return;\n        previewDetail.replaceChildren(section('Rotation preview', list(result.changes), scrollTable(table(['Key', 'Method', 'Places'], result.steps.map(step => [step.hint ?? 'Hint unavailable', step.method, step.services.join(', ')]), 'Planned changes')), ...(result.warnings.length ? [section('Review before rotating', list(result.warnings))] : [])));\n        const count = result.steps.length;\n        const label = `Rotate ${count} ${count === 1 ? 'key' : 'keys'}`;\n        if (!count) {\n            message(feedback, 'No changes planned', 'Choose another key or review the plan warnings.');\n            return;\n        }\n        if (session.readOnly) {\n            message(feedback, 'Read-only preview', 'This preview does not change keys. Open keysentry ui in your terminal to rotate them.');\n            return;\n        }\n        if (!await confirmAction({ title: 'Confirm rotation', changes: result.changes, button: label, signal: scope.signal }) || scope.signal.aborted)\n            return;\n        await postWithPasskey('rotate/execute', { planId: result.planId, planHash: result.planHash });\n        if (!scope.signal.aborted) {\n            message(feedback, 'Rotation requested', 'Check progress and the grace deadline below.');\n            await refresh();\n        }\n    });\n    const drill = taskButton('Run a drill', feedback, async () => {\n        const result = await post('drill', {});\n        if (!scope.signal.aborted)\n            message(feedback, 'Drill complete', `Readiness ${result.score}/100. ${result.reasons.join(' ')}`, 'ok');\n    });\n    showProgress();\n    root.append(paragraph('Preview the exact changes before rotating. A drill checks readiness without changing keys.'), choices, actions(preview, drill), feedback, previewDetail, section('Rotation progress', progress));\n    scope.onMount(() => { mounted = true; schedule(); startClock(); });\n    return root;\n}\n","sha256":"+LSG/hAbpJtSGMLjwZn8mDaLEIiJSefrt2jPNqCnKEg="},
  "/app/screens/settings.js": {"type":"text/javascript; charset=utf-8","body":"import { get, postWithPasskey } from '../api.js';\nimport { button } from '../components.js';\nimport { actions, el, field, input, lifetime, message, paragraph, status, taskButton } from './components-b.js';\nexport async function renderSettings(session) {\n    const root = el('div', undefined, 'screen-b');\n    const life = lifetime(root);\n    const current = await get('settings');\n    if (life.signal.aborted)\n        return root;\n    const feedback = status();\n    const form = el('form', undefined, 'b-form');\n    form.addEventListener('submit', event => event.preventDefault());\n    const grace = input('graceMinutes', 'number', String(current.graceMinutes));\n    grace.min = '0';\n    grace.step = 'any';\n    grace.required = true;\n    const rotate = input('rotateEveryDays', 'number', String(current.rotateEveryDays));\n    rotate.min = '1';\n    rotate.max = '36500';\n    rotate.step = '1';\n    rotate.required = true;\n    const digest = el('select');\n    digest.name = 'digestDay';\n    for (const [value, label] of [['off', 'Off'], ['mon', 'Monday'], ['tue', 'Tuesday'], ['wed', 'Wednesday'], ['thu', 'Thursday'], ['fri', 'Friday'], ['sat', 'Saturday'], ['sun', 'Sunday']]) {\n        const option = el('option', label);\n        option.value = value;\n        digest.append(option);\n    }\n    digest.value = current.digestDay;\n    const hints = input('showHints', 'checkbox');\n    hints.checked = current.showHints;\n    for (const control of [grace, rotate, digest, hints])\n        control.disabled = session.readOnly;\n    const capList = el('div', undefined, 'b-form');\n    const caps = [];\n    const addCap = (name = '', amount = '') => {\n        const row = el('div', undefined, 'b-cap-row');\n        const provider = input('spendCapKey', 'text', name);\n        provider.required = true;\n        provider.disabled = session.readOnly;\n        const value = input('spendCapUsd', 'number', amount);\n        value.required = true;\n        value.min = '0';\n        value.step = 'any';\n        value.disabled = session.readOnly;\n        const item = { name: provider, amount: value, row };\n        caps.push(item);\n        const remove = button('Remove cap', () => { const index = caps.indexOf(item); if (index >= 0)\n            caps.splice(index, 1); row.remove(); }, 'secondary');\n        remove.disabled = session.readOnly;\n        row.append(field('Provider or key', provider), field('Spend cap (USD)', value), remove);\n        capList.append(row);\n    };\n    for (const [key, value] of Object.entries(current.spendCapsUsd))\n        addCap(key, String(value));\n    const add = button('Add spend cap', () => addCap(), 'secondary');\n    add.disabled = session.readOnly;\n    const save = taskButton('Save settings', feedback, async () => {\n        if (life.signal.aborted)\n            return;\n        const graceMinutes = Number(grace.value);\n        const rotateEveryDays = Number(rotate.value);\n        const values = [];\n        const names = new Set();\n        let valid = grace.value !== '' && Number.isFinite(graceMinutes) && graceMinutes >= 0 && Number.isSafeInteger(graceMinutes * 60)\n            && rotate.value !== '' && Number.isInteger(rotateEveryDays) && rotateEveryDays >= 1 && rotateEveryDays <= 36500;\n        for (const cap of caps) {\n            const name = cap.name.value.trim();\n            const amount = Number(cap.amount.value);\n            if (!name || names.has(name) || cap.amount.value === '' || !Number.isFinite(amount) || amount < 0)\n                valid = false;\n            names.add(name);\n            values.push([name, amount]);\n        }\n        if (!valid || !form.reportValidity()) {\n            message(feedback, 'Review the numbers', 'Use a nonnegative grace period in whole seconds, a whole rotation interval from 1 to 36500 days, and nonnegative spend caps with unique names.', 'attention');\n            return;\n        }\n        const body = { graceMinutes, rotateEveryDays, spendCapsUsd: Object.fromEntries(values), digestDay: digest.value, showHints: hints.checked };\n        await postWithPasskey('settings/update', body);\n        if (!life.signal.aborted)\n            message(feedback, 'Settings saved', 'These settings will be used for future plans, reminders and notifications.', 'ok');\n    }, session.readOnly);\n    save.type = 'submit';\n    form.append(paragraph('Saving changes the defaults for future plans, rotation reminders, spend caps and the weekly digest. Existing armed plans keep their signed settings.'), field('Grace period (minutes)', grace), field('Rotate every (days)', rotate), field('Weekly digest', digest), field('Include key hints in notifications', hints), el('h2', 'Spend caps'), paragraph('Spend caps are saved here. Applying a provider limit is a separate action where supported.'), capList, actions(add), actions(save));\n    root.append(form, feedback);\n    return root;\n}\n","sha256":"vuHH74rxR1AsGVe7r7lWRM+JhmJNlt3sM+VlItJHDhs="},
  "/app/styles.css": {"type":"text/css; charset=utf-8","body":":root {\n  color-scheme: light dark;\n  --bg: #f3f6f8;\n  --surface: #ffffff;\n  --ink: #1b2533;\n  --muted: #566170;\n  --line: #d3dae1;\n  --control-line: #7b8594;\n  --brass: #8a5e0c;\n  --ok: #1d7349;\n  --attention: #9a4a00;\n  --stop: #b42318;\n  --info: #24569e;\n  --space-1: 4px;\n  --space-2: 8px;\n  --space-3: 12px;\n  --space-4: 16px;\n  --space-6: 24px;\n  --space-8: 32px;\n  --space-12: 48px;\n  --radius-tag: 10px;\n  --radius-button: 6px;\n  --radius-dialog: 12px;\n  --radius-control: 4px;\n  --text-small: 13px;\n  --text-body: 16px;\n  --text-section: 20px;\n  --text-page: 25px;\n  --text-display: 31px;\n  --font-body: system-ui, -apple-system, \"Segoe UI\", Roboto, \"Noto Sans\", sans-serif;\n  --font-mono: ui-monospace, \"Cascadia Mono\", \"SF Mono\", Menlo, Consolas, monospace;\n  --panel-duration: 160ms;\n  font-family: var(--font-body);\n  font-size: var(--text-body);\n  line-height: 1.5;\n  font-variant-numeric: tabular-nums;\n  color: var(--ink);\n  background: var(--bg);\n}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n    --bg: #152030;\n    --surface: #1c2a3d;\n    --ink: #e6ecf2;\n    --muted: #a5b1bf;\n    --line: #30405a;\n    --control-line: #71839c;\n    --brass: #d8a64a;\n    --ok: #5cc48f;\n    --attention: #f0a35e;\n    --stop: #f28b82;\n    --info: #8db4f0;\n  }\n}\n\n* { box-sizing: border-box; }\nbody { margin: 0; min-width: 280px; }\nbutton, input, select, textarea { font: inherit; }\nbutton, a, input, select, textarea { -webkit-tap-highlight-color: transparent; }\nbutton { cursor: pointer; }\nbutton:disabled { cursor: default; opacity: 0.65; }\na { color: var(--info); text-underline-offset: 3px; }\na:hover { text-decoration-thickness: 2px; }\n:focus-visible { outline: 3px solid var(--brass); outline-offset: 2px; }\n[hidden] { display: none !important; }\nh1, h2, h3, p { margin-block: 0 var(--space-4); }\nh1, .page-heading { font-size: var(--text-page); font-weight: 650; line-height: 1.3; }\nh2 { font-size: var(--text-section); font-weight: 600; line-height: 1.4; }\nh3 { font-size: var(--text-body); font-weight: 600; }\np { max-width: 72ch; }\ncode, pre, .key-tag-hint, .masked-value-output { font-family: var(--font-mono); font-size: 0.9375em; }\npre { overflow-x: auto; }\ninput, textarea, select {\n  color: var(--ink);\n  background: var(--surface);\n  border: 1px solid var(--control-line);\n  border-radius: var(--radius-control);\n  padding: var(--space-2) var(--space-3);\n  max-width: 100%;\n}\n\n.skip-link {\n  position: absolute;\n  top: var(--space-2);\n  left: var(--space-2);\n  z-index: 10;\n  padding: var(--space-2) var(--space-4);\n  background: var(--surface);\n  border: 1px solid var(--control-line);\n  border-radius: var(--radius-button);\n  transform: translateY(-160%);\n}\n.skip-link:focus { transform: translateY(0); }\n.app-shell { min-height: 100vh; }\n.app-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: var(--space-4) var(--space-6);\n  padding: var(--space-6) var(--space-8);\n  border-bottom: 1px solid var(--line);\n  background: var(--surface);\n}\n.app-brand { color: var(--ink); font-size: var(--text-section); font-weight: 650; text-decoration: none; }\n.app-header-links { display: flex; flex-wrap: wrap; gap: var(--space-3) var(--space-6); }\n.app-body { display: grid; grid-template-columns: 200px minmax(0, 1fr); }\n.app-nav { padding: var(--space-6) var(--space-4); border-right: 1px solid var(--line); }\n.app-nav a {\n  display: block;\n  margin-bottom: var(--space-1);\n  padding: var(--space-2) var(--space-3);\n  color: var(--muted);\n  border-radius: var(--radius-button);\n  text-decoration: none;\n}\n.app-nav a:hover { color: var(--ink); background: var(--surface); }\n.app-nav a[aria-current=\"page\"] { color: var(--ink); background: var(--surface); font-weight: 600; }\n.page { min-width: 0; padding: var(--space-8); }\n.read-only-notice { margin-bottom: var(--space-6); }\n.empty-state { max-width: 72ch; padding: var(--space-6) 0; }\n.empty-state p { color: var(--muted); }\n.button {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: var(--space-2);\n  min-height: 44px;\n  padding: var(--space-2) var(--space-4);\n  color: var(--surface);\n  background: var(--ink);\n  border: 1px solid var(--ink);\n  border-radius: var(--radius-button);\n  font-weight: 600;\n  text-decoration: none;\n}\n.button.secondary, .button-secondary { color: var(--ink); background: var(--surface); border-color: var(--control-line); }\n.button.danger, .button-danger { color: var(--surface); background: var(--stop); border-color: var(--stop); }\n.notice {\n  --notice-color: var(--info);\n  max-width: 72ch;\n  padding: var(--space-4) var(--space-6);\n  background: var(--surface);\n  border: 1px solid var(--line);\n  border-left: 4px solid var(--notice-color);\n  border-radius: var(--radius-control);\n}\n.notice h2, .notice h3, .notice strong { color: var(--notice-color); }\n.notice-status { display: block; color: var(--notice-color); margin-bottom: var(--space-2); }\n.notice p:last-child { margin-bottom: 0; }\n.notice-ok { --notice-color: var(--ok); }\n.notice-attention { --notice-color: var(--attention); }\n.notice-stop { --notice-color: var(--stop); }\n.notice-info { --notice-color: var(--info); }\n.key-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: var(--space-4); }\n.key-tag {\n  position: relative;\n  isolation: isolate;\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: var(--space-2);\n  min-height: 132px;\n  width: 100%;\n  padding: var(--space-6) var(--space-6) var(--space-6) var(--space-12);\n  color: var(--ink);\n  background: transparent;\n  border: 0;\n  border-radius: var(--radius-tag);\n  text-align: left;\n}\n/* Mask only the tag surface so the button's focus outline stays fully visible. */\n.key-tag::after {\n  position: absolute;\n  z-index: -1;\n  inset: 0;\n  content: \"\";\n  background: var(--surface);\n  border: 1px solid var(--line);\n  border-radius: inherit;\n  mask: radial-gradient(circle at 20px 50%, transparent 5px, #000 5.5px);\n}\n.key-tag::before {\n  position: absolute;\n  content: \"\";\n  left: 12px;\n  top: calc(50% - 8px);\n  width: 16px;\n  height: 16px;\n  border: 2px solid var(--brass);\n  border-radius: 50%;\n}\n.key-tag-provider { color: var(--brass); font-weight: 600; }\n.key-tag-hint { overflow-wrap: anywhere; }\n.key-tag-meta { color: var(--muted); font-size: var(--text-small); }\n.key-tag-state { color: var(--muted); font-size: var(--text-small); }\n.table-scroll { width: 100%; overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius-control); }\n.data-table { width: 100%; border-collapse: collapse; text-align: left; background: var(--surface); }\n.data-table caption { padding: var(--space-4); text-align: left; font-weight: 600; }\n.data-table th, .data-table td { padding: var(--space-3) var(--space-4); border-top: 1px solid var(--line); vertical-align: top; }\n.data-table th { position: sticky; top: 0; font-weight: 600; background: var(--surface); }\n.confirm-dialog {\n  max-width: min(560px, calc(100vw - 32px));\n  max-height: calc(100vh - 48px);\n  padding: var(--space-6);\n  color: var(--ink);\n  background: var(--surface);\n  border: 1px solid var(--line);\n  border-radius: var(--radius-dialog);\n  box-shadow: 0 12px 32px rgb(0 0 0 / 0.18);\n}\n.confirm-dialog::backdrop { background: rgb(0 0 0 / 0.35); }\n.confirm-dialog li { margin-block: var(--space-2); }\n.dialog-actions, .value-actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: var(--space-3); margin-top: var(--space-6); }\n.masked-value { max-width: 72ch; }\n.masked-value-output { display: block; overflow-wrap: anywhere; padding: var(--space-3); border: 1px solid var(--line); border-radius: var(--radius-control); background: var(--surface); }\n.masked-value .value-actions { justify-content: flex-start; margin-top: var(--space-3); }\n\n@media (max-width: 720px) {\n  .app-header { padding: var(--space-4) var(--space-6); }\n  .app-body { display: block; }\n  .app-nav { display: flex; flex-wrap: wrap; gap: var(--space-1); padding: var(--space-3) var(--space-4); border-right: 0; border-bottom: 1px solid var(--line); }\n  .app-nav a { margin-bottom: 0; }\n  .page { padding: var(--space-6); }\n  .key-grid { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  :root { --panel-duration: 0ms; }\n  *, *::before, *::after { animation-duration: 0ms !important; transition-duration: 0ms !important; scroll-behavior: auto !important; }\n}\n","sha256":"NILEVtbb78UXS0Spcv2cDndMRPoEcZLoMYHQpGCTLAQ="},
};
